           integer(ilp),intent(in) :: kl,ku,ldab,m,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(dp),intent(inout) :: ab(ldab,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j,jp,ju,km,kv
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! kv is the number of superdiagonals in the factor u, allowing for
           ! fill-in.
           kv = ku + kl
           ! test the input parameters.
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (ldab < kl + kv + 1) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('DGBTF2',-info)
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) return
           ! gaussian elimination with partial pivoting
           ! set fill-in elements in columns ku+2 to kv to zero.
           do j = ku + 2,min(kv,n)
              do i = kv - j + 2,kl
                 ab(i,j) = zero
              end do
           end do
           ! ju is the index of the last column affected by the current stage
           ! of the factorization.
           ju = 1
           loop_40: do j = 1,min(m,n)
              ! set fill-in elements in column j+kv to zero.
              if (j + kv <= n) then
                 do i = 1,kl
                    ab(i,j + kv) = zero
                 end do
              end if
              ! find pivot and test for singularity. km is the number of
              ! subdiagonal elements in the current column.
              km = min(kl,m - j)
              jp = la_idamax(km + 1,ab(kv + 1,j),1)
              ipiv(j) = jp + j - 1
              if (ab(kv + jp,j) /= zero) then
                 ju = max(ju,min(j + ku + jp - 1,n))
                 ! apply interchange to columns j to ju.
                 if (jp /= 1) call la_dswap(ju - j + 1,ab(kv + jp,j),ldab - 1,ab(kv + 1,j),ldab - &
                           1)
                 if (km > 0) then
                    ! compute multipliers.
                    call la_dscal(km,one/ab(kv + 1,j),ab(kv + 2,j),1)
                    ! update trailing submatrix within the band.
                    if (ju > j) call la_dger(km,ju - j,-one,ab(kv + 2,j),1,ab(kv,j + 1), &
                              ldab - 1,ab(kv + 1,j + 1),ldab - 1)
                 end if
              else
                 ! if pivot is zero, set info to the index of the pivot
                 ! unless a zero pivot has already been found.
                 if (info == 0) info = j
              end if
           end do loop_40
           return
     end subroutine la_dgbtf2
