     !> SGBTRS: solves a system of linear equations
     !> A * X = B  or  A**T * X = B
     !> with a general band matrix A using the LU factorization computed
     !> by SGBTRF.

     pure subroutine la_sgbtrs(trans,n,kl,ku,nrhs,ab,ldab,ipiv,b,ldb,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,ldb,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(sp),intent(in) :: ab(ldab,*)
           real(sp),intent(inout) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lnoti,notran
           integer(ilp) :: i,j,kd,l,lm
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (nrhs < 0) then
              info = -5
           else if (ldab < (2*kl + ku + 1)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('SGBTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           kd = ku + kl + 1
           lnoti = kl > 0
           if (notran) then
              ! solve  a*x = b.
              ! solve l*x = b, overwriting b with x.
              ! l is represented as a product of permutations and unit lower
              ! triangular matrices l = p(1) * l(1) * ... * p(n-1) * l(n-1),
              ! where each transformation l(i) is a rank-one modification of
              ! the identity matrix.
              if (lnoti) then
                 do j = 1,n - 1
                    lm = min(kl,n - j)
                    l = ipiv(j)
                    if (l /= j) call la_sswap(nrhs,b(l,1),ldb,b(j,1),ldb)
                    call la_sger(lm,nrhs,-one,ab(kd + 1,j),1,b(j,1),ldb,b(j + 1,1) &
                              ,ldb)
                 end do
              end if
              do i = 1,nrhs
