     !> SGTTRF: computes an LU factorization of a real tridiagonal matrix A
     !> using elimination with partial pivoting and row interchanges.
     !> The factorization has the form
     !> A = L * U
     !> where L is a product of permutation and unit lower bidiagonal
     !> matrices and U is upper triangular with nonzeros in only the main
     !> diagonal and first two superdiagonals.

     pure subroutine la_sgttrf(n,dl,d,du,du2,ipiv,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(sp),intent(inout) :: d(*),dl(*),du(*)
           real(sp),intent(out) :: du2(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i
           real(sp) :: fact,temp
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           info = 0
           if (n < 0) then
              info = -1
              call la_xerbla('SGTTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! initialize ipiv(i) = i and du2(i) = 0
           do i = 1,n
              ipiv(i) = i
           end do
           do i = 1,n - 2
              du2(i) = zero
           end do
           do i = 1,n - 2
              if (abs(d(i)) >= abs(dl(i))) then
                 ! no row interchange required, eliminate dl(i)
                 if (d(i) /= zero) then
                    fact = dl(i)/d(i)
                    dl(i) = fact
                    d(i + 1) = d(i + 1) - fact*du(i)
                 end if
              else
                 ! interchange rows i and i+1, eliminate dl(i)
                 fact = d(i)/dl(i)
                 d(i) = dl(i)
                 dl(i) = fact
                 temp = du(i)
                 du(i) = d(i + 1)
                 d(i + 1) = temp - fact*d(i + 1)
                 du2(i) = du(i + 1)
                 du(i + 1) = -fact*du(i + 1)
                 ipiv(i) = i + 1
              end if
           end do
           if (n > 1) then
              i = n - 1
              if (abs(d(i)) >= abs(dl(i))) then
                 if (d(i) /= zero) then
                    fact = dl(i)/d(i)
                    dl(i) = fact
                    d(i + 1) = d(i + 1) - fact*du(i)
                 end if
              else
                 fact = d(i)/dl(i)
                 d(i) = dl(i)
                 dl(i) = fact
                 temp = du(i)
                 du(i) = d(i + 1)
                 d(i + 1) = temp - fact*d(i + 1)
                 ipiv(i) = i + 1
              end if
           end if
           ! check for a zero on the diagonal of u.
           do i = 1,n
              if (d(i) == zero) then
                 info = i
                 go to 50
              end if
           end do
           50 continue
           return
     end subroutine la_sgttrf
