                    do i = 1,n - 1
                       if (ipiv(i) == i) then
                          b(i + 1,j) = b(i + 1,j) - dl(i)*b(i,j)
                       else
                          temp = b(i,j)
                          b(i,j) = b(i + 1,j)
                          b(i + 1,j) = temp - dl(i)*b(i,j)
                       end if
                    end do
                    ! solve u*x = b.
                    b(n,j) = b(n,j)/d(n)
                    if (n > 1) b(n - 1,j) = (b(n - 1,j) - du(n - 1)*b(n,j))/d(n - 1)
                    do i = n - 2,1,-1
                       b(i,j) = (b(i,j) - du(i)*b(i + 1,j) - du2(i)*b(i + 2,j))/d(i)

                    end do
                 end do
              end if
           else
              ! solve a**t * x = b.
              if (nrhs <= 1) then
