                 j = 1
                 70 continue
                 b(1,j) = b(1,j)/d(1)
                 if (n > 1) b(2,j) = (b(2,j) - du(1)*b(1,j))/d(2)
                 do i = 3,n
                    b(i,j) = (b(i,j) - du(i - 1)*b(i - 1,j) - du2(i - 2)*b(i - 2,j))/d(i &
                              )
                 end do
                 ! solve l**t*x = b.
                 do i = n - 1,1,-1
                    ip = ipiv(i)
                    temp = b(i,j) - dl(i)*b(i + 1,j)
                    b(i,j) = b(ip,j)
                    b(ip,j) = temp
                 end do
                 if (j < nrhs) then
                    j = j + 1
                    go to 70
                 end if
              else
                 do j = 1,nrhs
                    ! solve u**t*x = b.
                    b(1,j) = b(1,j)/d(1)
                    if (n > 1) b(2,j) = (b(2,j) - du(1)*b(1,j))/d(2)
                    do i = 3,n
                       b(i,j) = (b(i,j) - du(i - 1)*b(i - 1,j) - du2(i - 2)*b(i - 2,j))/d( &
                                  i)
                    end do
                    do i = n - 1,1,-1
                       if (ipiv(i) == i) then
                          b(i,j) = b(i,j) - dl(i)*b(i + 1,j)
                       else
                          temp = b(i + 1,j)
                          b(i + 1,j) = b(i,j) - dl(i)*temp
                          b(i,j) = temp
                       end if
                    end do
                 end do
              end if
           end if
