     !> SLA_GBRPVGRW: computes the reciprocal pivot growth factor
     !> norm(A)/norm(U). The "max absolute element" norm is used. If this is
     !> much less than 1, the stability of the LU factorization of the
     !> (equilibrated) matrix A could be poor. This also means that the
     !> solution X, estimated condition numbers, and error bounds could be
     !> unreliable.

     pure real(sp) function la_sla_gbrpvgrw(n,kl,ku,ncols,ab,ldab,afb,ldafb)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: n,kl,ku,ncols,ldab,ldafb
           ! Array Arguments
           real(sp),intent(in) :: ab(ldab,*),afb(ldafb,*)
        ! =====================================================================
           ! Local Scalars
           integer(ilp) :: i,j,kd
           real(sp) :: amax,umax,rpvgrw
           ! Intrinsic Functions
           intrinsic :: abs,max,min
           ! Executable Statements
           rpvgrw = one
           kd = ku + 1
           do j = 1,ncols
              amax = zero
              umax = zero
              do i = max(j - ku,1),min(j + kl,n)
                 amax = max(abs(ab(kd + i - j,j)),amax)
              end do
              do i = max(j - ku,1),j
                 umax = max(abs(afb(kd + i - j,j)),umax)
              end do
              if (umax /= 0.0_sp) then
                 rpvgrw = min(amax/umax,rpvgrw)
              end if
           end do
           la_sla_gbrpvgrw = rpvgrw
     end function la_sla_gbrpvgrw
