     !> SLAQGB: equilibrates a general M by N band matrix A with KL
     !> subdiagonals and KU superdiagonals using the row and scaling factors
     !> in the vectors R and C.

     pure subroutine la_slaqgb(m,n,kl,ku,ab,ldab,r,c,rowcnd,colcnd,amax,equed)
        use la_constants_sp

        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(out) :: equed
           integer(ilp),intent(in) :: kl,ku,ldab,m,n
           real(sp),intent(in) :: amax,colcnd,rowcnd
           ! Array Arguments
           real(sp),intent(inout) :: ab(ldab,*)
           real(sp),intent(in) :: c(*),r(*)
        ! =====================================================================
           ! Parameters
           real(sp),parameter :: thresh = 0.1e+0_sp

           ! Local Scalars
           integer(ilp) :: i,j
           real(sp) :: cj,large,small
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! quick return if possible
           if (m <= 0 .or. n <= 0) then
              equed = 'N'
              return
           end if
           ! initialize large and small.
           small = la_slamch('SAFE MINIMUM')/la_slamch('PRECISION')
           large = one/small
           if (rowcnd >= thresh .and. amax >= small .and. amax <= large) then
              ! no row scaling
              if (colcnd >= thresh) then
                 ! no column scaling
                 equed = 'N'
              else
                 ! column scaling
                 do j = 1,n
                    cj = c(j)
                    do i = max(1,j - ku),min(m,j + kl)
                       ab(ku + 1 + i - j,j) = cj*ab(ku + 1 + i - j,j)
                    end do
                 end do
                 equed = 'C'
              end if
           else if (colcnd >= thresh) then
              ! row scaling, no column scaling
              do j = 1,n
                 do i = max(1,j - ku),min(m,j + kl)
                    ab(ku + 1 + i - j,j) = r(i)*ab(ku + 1 + i - j,j)
                 end do
              end do
              equed = 'R'
           else
              ! row and column scaling
              do j = 1,n
                 cj = c(j)
                 do i = max(1,j - ku),min(m,j + kl)
                    ab(ku + 1 + i - j,j) = cj*r(i)*ab(ku + 1 + i - j,j)
                 end do
              end do
              equed = 'B'
           end if
           return
     end subroutine la_slaqgb
