     !> DLASWP: performs a series of row interchanges on the matrix A.
     !> One row interchange is initiated for each of rows K1 through K2 of A.

     pure subroutine la_dlaswp(n,a,lda,k1,k2,ipiv,incx)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: incx,k1,k2,lda,n
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(dp),intent(inout) :: a(lda,*)
       ! =====================================================================
           ! Local Scalars
           integer(ilp) :: i,i1,i2,inc,ip,ix,ix0,j,k,n32
           real(dp) :: temp
           ! Executable Statements
           ! interchange row i with row ipiv(k1+(i-k1)*abs(incx)) for each of rows
           ! k1 through k2.
           if (incx > 0) then
              ix0 = k1
              i1 = k1
              i2 = k2
              inc = 1
           else if (incx < 0) then
              ix0 = k1 + (k1 - k2)*incx
              i1 = k2
              i2 = k1
              inc = -1
           else
              return
           end if
           n32 = (n/32)*32
           if (n32 /= 0) then
              do j = 1,n32,32
                 ix = ix0
                 do i = i1,i2,inc
                    ip = ipiv(ix)
                    if (ip /= i) then
                       do k = j,j + 31
                          temp = a(i,k)
                          a(i,k) = a(ip,k)
                          a(ip,k) = temp
                       end do
                    end if
                    ix = ix + incx
                 end do
              end do
           end if
           if (n32 /= n) then
              n32 = n32 + 1
              ix = ix0
              do i = i1,i2,inc
                 ip = ipiv(ix)
                 if (ip /= i) then
                    do k = n32,n
                       temp = a(i,k)
                       a(i,k) = a(ip,k)
                       a(ip,k) = temp
                    end do
                 end if
                 ix = ix + incx
              end do
           end if
           return
     end subroutine la_dlaswp
