     !> SGBCON: estimates the reciprocal of the condition number of a real
     !> general band matrix A, in either the 1-norm or the infinity-norm,
     !> using the LU factorization computed by SGBTRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as
     !> RCOND = 1 / ( norm(A) * norm(inv(A)) ).

     pure subroutine la_sgbcon(norm,n,kl,ku,ab,ldab,ipiv,anorm,rcond,work,iwork, &
               info)
        use la_constants_sp,only:zero,one
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: norm
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,n
           real(sp),intent(in) :: anorm
           real(sp),intent(out) :: rcond
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(sp),intent(in) :: ab(ldab,*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lnoti,onenrm
           character :: normin
           integer(ilp) :: ix,j,jp,kase,kase1,kd,lm
           real(sp) :: ainvnm,scale,smlnum,t
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           onenrm = norm == '1' .or. la_lsame(norm,'O')
           if (.not. onenrm .and. .not. la_lsame(norm,'I')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (ldab < 2*kl + ku + 1) then
              info = -6
           else if (anorm < zero) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('SGBCON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           smlnum = la_slamch('SAFE MINIMUM')
           ! estimate the norm of inv(a).
           ainvnm = zero
           normin = 'N'
           if (onenrm) then
              kase1 = 1
           else
              kase1 = 2
           end if
           kd = kl + ku + 1
           lnoti = kl > 0
           kase = 0
           10 continue
           call la_slacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              if (kase == kase1) then
                 ! multiply by inv(l).
                 if (lnoti) then
                    do j = 1,n - 1
                       lm = min(kl,n - j)
                       jp = ipiv(j)
                       t = work(jp)
                       if (jp /= j) then
                          work(jp) = work(j)
                          work(j) = t
                       end if
                       call la_saxpy(lm,-t,ab(kd + 1,j),1,work(j + 1),1)
                    end do
                 end if
                 ! multiply by inv(u).
                 call la_slatbs('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,kl + ku,ab, &
                           ldab,work,scale,work(2*n + 1),info)
              else
                 ! multiply by inv(u**t).
                 call la_slatbs('UPPER','TRANSPOSE','NON-UNIT',normin,n,kl + ku,ab,ldab, &
                           work,scale,work(2*n + 1),info)
                 ! multiply by inv(l**t).
                 if (lnoti) then
                    do j = n - 1,1,-1
                       lm = min(kl,n - j)
                       work(j) = work(j) - la_sdot(lm,ab(kd + 1,j),1,work(j + 1),1)

                       jp = ipiv(j)
                       if (jp /= j) then
                          t = work(jp)
                          work(jp) = work(j)
                          work(j) = t
                       end if
                    end do
                 end if
              end if
              ! divide x by 1/scale if doing so will not cause overflow.
              normin = 'Y'
              if (scale /= one) then
                 ix = la_isamax(n,work,1)
                 if (scale < abs(work(ix))*smlnum .or. scale == zero) go to 40
                 call la_srscl(n,scale,work,1)
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           40 continue
           return
     end subroutine la_sgbcon
