                 ! multiply by inv(u).
                 call la_qlatbs('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,kl + ku,ab, &
                           ldab,work,scale,work(2*n + 1),info)
              else
                 ! multiply by inv(u**t).
                 call la_qlatbs('UPPER','TRANSPOSE','NON-UNIT',normin,n,kl + ku,ab,ldab, &
                           work,scale,work(2*n + 1),info)
                 ! multiply by inv(l**t).
                 if (lnoti) then
                    do j = n - 1,1,-1
                       lm = min(kl,n - j)
                       work(j) = work(j) - la_qdot(lm,ab(kd + 1,j),1,work(j + 1),1)

                       jp = ipiv(j)
                       if (jp /= j) then
                          t = work(jp)
                          work(jp) = work(j)
                          work(j) = t
                       end if
                    end do
                 end if
              end if
              ! divide x by 1/scale if doing so will not cause overflow.
              normin = 'Y'
              if (scale /= one) then
                 ix = la_iqamax(n,work,1)
                 if (scale < abs(work(ix))*smlnum .or. scale == zero) go to 40
                 call la_qrscl(n,scale,work,1)
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           40 continue
           return
     end subroutine la_qgbcon
#endif

     !> SGBEQU: computes row and column scalings intended to equilibrate an
     !> M-by-N band matrix A and reduce its condition number.  R returns the
     !> row scale factors and C the column scale factors, chosen to try to
     !> make the largest element in each row and column of the matrix B with
     !> elements B(i,j)=R(i)*A(i,j)*C(j) have absolute value 1.
     !> R(i) and C(j) are restricted to be between SMLNUM = smallest safe
     !> number and BIGNUM = largest safe number.  Use of these scaling
     !> factors is not guaranteed to reduce the condition number of A but
     !> works well in practice.

     pure subroutine la_sgbequ(m,n,kl,ku,ab,ldab,r,c,rowcnd,colcnd,amax,info)
        use la_constants_sp,only:zero,one

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,m,n
           real(sp),intent(out) :: amax,colcnd,rowcnd
           ! Array Arguments
           real(sp),intent(in) :: ab(ldab,*)
           real(sp),intent(out) :: c(*),r(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j,kd
           real(sp) :: bignum,rcmax,rcmin,smlnum
           ! Intrinsic Functions
           intrinsic :: abs,max,min
           ! Executable Statements
           ! test the input parameters
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (ldab < kl + ku + 1) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('SGBEQU',-info)
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) then
              rowcnd = one
              colcnd = one
              amax = zero
              return
           end if
           ! get machine constants.
           smlnum = la_slamch('S')
           bignum = one/smlnum
           ! compute row scale factors.
           do i = 1,m
              r(i) = zero
           end do
           ! find the maximum element in each row.
           kd = ku + 1
           do j = 1,n
              do i = max(j - ku,1),min(j + kl,m)
                 r(i) = max(r(i),abs(ab(kd + i - j,j)))
              end do
           end do
           ! find the maximum and minimum scale factors.
           rcmin = bignum
           rcmax = zero
           do i = 1,m
              rcmax = max(rcmax,r(i))
              rcmin = min(rcmin,r(i))
           end do
           amax = rcmax
           if (rcmin == zero) then
              ! find the first zero scale factor and return an error code.
              do i = 1,m
                 if (r(i) == zero) then
                    info = i
                    return
                 end if
              end do
           else
              ! invert the scale factors.
              do i = 1,m
                 r(i) = one/min(max(r(i),smlnum),bignum)
              end do
              ! compute rowcnd = min(r(i)) / max(r(i))
              rowcnd = max(rcmin,smlnum)/min(rcmax,bignum)
           end if
           ! compute column scale factors
           do j = 1,n
              c(j) = zero
           end do
           ! find the maximum element in each column,
           ! assuming the row scaling computed above.
           kd = ku + 1
           do j = 1,n
              do i = max(j - ku,1),min(j + kl,m)
                 c(j) = max(c(j),abs(ab(kd + i - j,j))*r(i))
              end do
           end do
           ! find the maximum and minimum scale factors.
           rcmin = bignum
           rcmax = zero
           do j = 1,n
              rcmin = min(rcmin,c(j))
              rcmax = max(rcmax,c(j))
           end do
           if (rcmin == zero) then
              ! find the first zero scale factor and return an error code.
              do j = 1,n
                 if (c(j) == zero) then
                    info = m + j
                    return
                 end if
              end do
           else
              ! invert the scale factors.
              do j = 1,n
                 c(j) = one/min(max(c(j),smlnum),bignum)
              end do
              ! compute colcnd = min(c(j)) / max(c(j))
              colcnd = max(rcmin,smlnum)/min(rcmax,bignum)
           end if
           return
     end subroutine la_sgbequ
