     !> SGBEQUB: computes row and column scalings intended to equilibrate an
     !> M-by-N matrix A and reduce its condition number.  R returns the row
     !> scale factors and C the column scale factors, chosen to try to make
     !> the largest element in each row and column of the matrix B with
     !> elements B(i,j)=R(i)*A(i,j)*C(j) have an absolute value of at most
     !> the radix.
     !> R(i) and C(j) are restricted to be a power of the radix between
     !> SMLNUM = smallest safe number and BIGNUM = largest safe number.  Use
     !> of these scaling factors is not guaranteed to reduce the condition
     !> number of A but works well in practice.
     !> This routine differs from SGEEQU by restricting the scaling factors
     !> to a power of the radix.  Barring over- and underflow, scaling by
     !> these factors introduces no additional rounding errors.  However, the
     !> scaled entries' magnitudes are no longer approximately 1 but lie
     !> between sqrt(radix) and 1/sqrt(radix).

     pure subroutine la_sgbequb(m,n,kl,ku,ab,ldab,r,c,rowcnd,colcnd,amax,info)
        use la_constants_sp,only:zero,one

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,m,n
           real(sp),intent(out) :: amax,colcnd,rowcnd
           ! Array Arguments
           real(sp),intent(in) :: ab(ldab,*)
           real(sp),intent(out) :: c(*),r(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j,kd
           real(sp) :: bignum,rcmax,rcmin,smlnum,radix,logrdx
           ! Intrinsic Functions
           intrinsic :: abs,max,min,log
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (ldab < kl + ku + 1) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('SGBEQUB',-info)
              return
           end if
           ! quick return if possible.
           if (m == 0 .or. n == 0) then
              rowcnd = one
              colcnd = one
              amax = zero
              return
           end if
           ! get machine constants.  assume smlnum is a power of the radix.
           smlnum = la_slamch('S')
           bignum = one/smlnum
           radix = la_slamch('B')
           logrdx = log(radix)
           ! compute row scale factors.
           do i = 1,m
              r(i) = zero
           end do
           ! find the maximum element in each row.
           kd = ku + 1
           do j = 1,n
              do i = max(j - ku,1),min(j + kl,m)
                 r(i) = max(r(i),abs(ab(kd + i - j,j)))
              end do
           end do
           do i = 1,m
              if (r(i) > zero) then
                 r(i) = radix**int(log(r(i))/logrdx,KIND=ilp)
              end if
           end do
           ! find the maximum and minimum scale factors.
           rcmin = bignum
           rcmax = zero
           do i = 1,m
              rcmax = max(rcmax,r(i))
              rcmin = min(rcmin,r(i))
           end do
           amax = rcmax
           if (rcmin == zero) then
              ! find the first zero scale factor and return an error code.
              do i = 1,m
                 if (r(i) == zero) then
                    info = i
                    return
                 end if
              end do
           else
              ! invert the scale factors.
              do i = 1,m
                 r(i) = one/min(max(r(i),smlnum),bignum)
              end do
              ! compute rowcnd = min(r(i)) / max(r(i)).
              rowcnd = max(rcmin,smlnum)/min(rcmax,bignum)
           end if
           ! compute column scale factors.
           do j = 1,n
              c(j) = zero
           end do
           ! find the maximum element in each column,
           ! assuming the row scaling computed above.
           do j = 1,n
              do i = max(j - ku,1),min(j + kl,m)
                 c(j) = max(c(j),abs(ab(kd + i - j,j))*r(i))
              end do
              if (c(j) > zero) then
                 c(j) = radix**int(log(c(j))/logrdx,KIND=ilp)
              end if
           end do
           ! find the maximum and minimum scale factors.
           rcmin = bignum
           rcmax = zero
           do j = 1,n
              rcmin = min(rcmin,c(j))
              rcmax = max(rcmax,c(j))
           end do
           if (rcmin == zero) then
              ! find the first zero scale factor and return an error code.
              do j = 1,n
                 if (c(j) == zero) then
                    info = m + j
                    return
                 end if
              end do
           else
              ! invert the scale factors.
              do j = 1,n
                 c(j) = one/min(max(c(j),smlnum),bignum)
              end do
              ! compute colcnd = min(c(j)) / max(c(j)).
              colcnd = max(rcmin,smlnum)/min(rcmax,bignum)
           end if
           return
     end subroutine la_sgbequb
     !> DGBEQUB: computes row and column scalings intended to equilibrate an
     !> M-by-N matrix A and reduce its condition number.  R returns the row
     !> scale factors and C the column scale factors, chosen to try to make
     !> the largest element in each row and column of the matrix B with
     !> elements B(i,j)=R(i)*A(i,j)*C(j) have an absolute value of at most
     !> the radix.
     !> R(i) and C(j) are restricted to be a power of the radix between
     !> SMLNUM = smallest safe number and BIGNUM = largest safe number.  Use
     !> of these scaling factors is not guaranteed to reduce the condition
     !> number of A but works well in practice.
     !> This routine differs from DGEEQU by restricting the scaling factors
     !> to a power of the radix.  Barring over- and underflow, scaling by
     !> these factors introduces no additional rounding errors.  However, the
     !> scaled entries' magnitudes are no longer approximately 1 but lie
     !> between sqrt(radix) and 1/sqrt(radix).

     pure subroutine la_dgbequb(m,n,kl,ku,ab,ldab,r,c,rowcnd,colcnd,amax,info)
        use la_constants_dp,only:zero,one

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,m,n
           real(dp),intent(out) :: amax,colcnd,rowcnd
           ! Array Arguments
           real(dp),intent(in) :: ab(ldab,*)
           real(dp),intent(out) :: c(*),r(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j,kd
           real(dp) :: bignum,rcmax,rcmin,smlnum,radix,logrdx
           ! Intrinsic Functions
           intrinsic :: abs,max,min,log
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (ldab < kl + ku + 1) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('DGBEQUB',-info)
              return
           end if
           ! quick return if possible.
           if (m == 0 .or. n == 0) then
              rowcnd = one
              colcnd = one
              amax = zero
              return
           end if
           ! get machine constants.  assume smlnum is a power of the radix.
           smlnum = la_dlamch('S')
           bignum = one/smlnum
           radix = la_dlamch('B')
           logrdx = log(radix)
           ! compute row scale factors.
           do i = 1,m
              r(i) = zero
           end do
           ! find the maximum element in each row.
           kd = ku + 1
           do j = 1,n
              do i = max(j - ku,1),min(j + kl,m)
                 r(i) = max(r(i),abs(ab(kd + i - j,j)))
              end do
           end do
           do i = 1,m
              if (r(i) > zero) then
                 r(i) = radix**int(log(r(i))/logrdx,KIND=ilp)
              end if
           end do
           ! find the maximum and minimum scale factors.
           rcmin = bignum
           rcmax = zero
           do i = 1,m
              rcmax = max(rcmax,r(i))
              rcmin = min(rcmin,r(i))
           end do
           amax = rcmax
           if (rcmin == zero) then
              ! find the first zero scale factor and return an error code.
              do i = 1,m
                 if (r(i) == zero) then
                    info = i
                    return
                 end if
              end do
           else
              ! invert the scale factors.
              do i = 1,m
                 r(i) = one/min(max(r(i),smlnum),bignum)
              end do
              ! compute rowcnd = min(r(i)) / max(r(i)).
              rowcnd = max(rcmin,smlnum)/min(rcmax,bignum)
           end if
           ! compute column scale factors.
           do j = 1,n
              c(j) = zero
           end do
           ! find the maximum element in each column,
           ! assuming the row scaling computed above.
           do j = 1,n
              do i = max(j - ku,1),min(j + kl,m)
                 c(j) = max(c(j),abs(ab(kd + i - j,j))*r(i))
              end do
              if (c(j) > zero) then
                 c(j) = radix**int(log(c(j))/logrdx,KIND=ilp)
              end if
           end do
           ! find the maximum and minimum scale factors.
           rcmin = bignum
           rcmax = zero
           do j = 1,n
              rcmin = min(rcmin,c(j))
              rcmax = max(rcmax,c(j))
           end do
           if (rcmin == zero) then
              ! find the first zero scale factor and return an error code.
              do j = 1,n
                 if (c(j) == zero) then
                    info = m + j
                    return
                 end if
              end do
           else
              ! invert the scale factors.
              do j = 1,n
                 c(j) = one/min(max(c(j),smlnum),bignum)
              end do
              ! compute colcnd = min(c(j)) / max(c(j)).
              colcnd = max(rcmin,smlnum)/min(rcmax,bignum)
           end if
           return
     end subroutine la_dgbequb
