     !> SGBRFS: improves the computed solution to a system of linear
     !> equations when the coefficient matrix is banded, and provides
     !> error bounds and backward error estimates for the solution.

     pure subroutine la_sgbrfs(trans,n,kl,ku,nrhs,ab,ldab,afb,ldafb,ipiv,b,ldb,x, &
               ldx,ferr,berr,work,iwork,info)
        use la_constants_sp,only:zero,one,two,three
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,ldafb,ldb,ldx,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(sp),intent(in) :: ab(ldab,*),afb(ldafb,*),b(ldb,*)
           real(sp),intent(out) :: berr(*),ferr(*),work(*)
           real(sp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           logical(lk) :: notran
           character :: transt
           integer(ilp) :: count,i,j,k,kase,kk,nz
           real(sp) :: eps,lstres,s,safe1,safe2,safmin,xk
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (nrhs < 0) then
              info = -5
           else if (ldab < kl + ku + 1) then
              info = -7
           else if (ldafb < 2*kl + ku + 1) then
              info = -9
           else if (ldb < max(1,n)) then
              info = -12
           else if (ldx < max(1,n)) then
              info = -14
           end if
           if (info /= 0) then
              call la_xerbla('SGBRFS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) then
              do j = 1,nrhs
                 ferr(j) = zero
                 berr(j) = zero
              end do
              return
           end if
           if (notran) then
              transt = 'T'
           else
              transt = 'N'
           end if
           ! nz = maximum number of nonzero elements in each row of a, plus 1
           nz = min(kl + ku + 2,n + 1)
           eps = la_slamch('EPSILON')
           safmin = la_slamch('SAFE MINIMUM')
           safe1 = nz*safmin
           safe2 = safe1/eps
           ! do for each right hand side
           loop_140: do j = 1,nrhs
              count = 1
              lstres = three
              20 continue
              ! loop until stopping criterion is satisfied.
              ! compute residual r = b - op(a) * x,
              ! where op(a) = a, a**t, or a**h, depending on trans.
              call la_scopy(n,b(1,j),1,work(n + 1),1)
              call la_sgbmv(trans,n,n,kl,ku,-one,ab,ldab,x(1,j),1,one,work(n + 1 &
                        ),1)
              ! compute componentwise relative backward error from formula
              ! max(i) ( abs(r(i)) / ( abs(op(a))*abs(x) + abs(b) )(i) )
              ! where abs(z) is the componentwise absolute value of the matrix
              ! or vector z.  if the i-th component of the denominator is less
              ! than safe2, then safe1 is added to the i-th components of the
              ! numerator and denominator before dividing.
              do i = 1,n
                 work(i) = abs(b(i,j))
              end do
              ! compute abs(op(a))*abs(x) + abs(b).
              if (notran) then
                 do k = 1,n
                    kk = ku + 1 - k
                    xk = abs(x(k,j))
                    do i = max(1,k - ku),min(n,k + kl)
                       work(i) = work(i) + abs(ab(kk + i,k))*xk
                    end do
                 end do
              else
                 do k = 1,n
                    s = zero
                    kk = ku + 1 - k
                    do i = max(1,k - ku),min(n,k + kl)
                       s = s + abs(ab(kk + i,k))*abs(x(i,j))
                    end do
                    work(k) = work(k) + s
                 end do
              end if
              s = zero
              do i = 1,n
                 if (work(i) > safe2) then
                    s = max(s,abs(work(n + i))/work(i))
                 else
                    s = max(s, (abs(work(n + i)) + safe1)/(work(i) + safe1))
                 end if
              end do
              berr(j) = s
              ! test stopping criterion. continue iterating if
                 ! 1) the residual berr(j) is larger than machine epsilon, and
                 ! 2) berr(j) decreased by at least a factor of 2 during the
                    ! last iteration, and
                 ! 3) at most itmax iterations tried.
              if (berr(j) > eps .and. two*berr(j) <= lstres .and. count <= itmax) then
                 ! update solution and try again.
                 call la_sgbtrs(trans,n,kl,ku,1,afb,ldafb,ipiv,work(n + 1),n,info)

                 call la_saxpy(n,one,work(n + 1),1,x(1,j),1)
                 lstres = berr(j)
                 count = count + 1
                 go to 20
              end if
              ! bound error from formula
              ! norm(x - xtrue) / norm(x) .le. ferr =
              ! norm( abs(inv(op(a)))*
                 ! ( abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) ))) / norm(x)
              ! where
                ! norm(z) is the magnitude of the largest component of z
                ! inv(op(a)) is the inverse of op(a)
                ! abs(z) is the componentwise absolute value of the matrix or
                   ! vector z
                ! nz is the maximum number of nonzeros in any row of a, plus 1
                ! eps is machine epsilon
              ! the i-th component of abs(r)+nz*eps*(abs(op(a))*abs(x)+abs(b))
              ! is incremented by safe1 if the i-th component of
              ! abs(op(a))*abs(x) + abs(b) is less than safe2.
              ! use la_slacn2 to estimate the infinity-norm of the matrix
                 ! inv(op(a)) * diag(w),
              ! where w = abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) )))
              do i = 1,n
                 if (work(i) > safe2) then
                    work(i) = abs(work(n + i)) + nz*eps*work(i)
                 else
                    work(i) = abs(work(n + i)) + nz*eps*work(i) + safe1
                 end if
              end do
              kase = 0
              100 continue
              call la_slacn2(n,work(2*n + 1),work(n + 1),iwork,ferr(j),kase,isave)

              if (kase /= 0) then
                 if (kase == 1) then
                    ! multiply by diag(w)*inv(op(a)**t).
                    call la_sgbtrs(transt,n,kl,ku,1,afb,ldafb,ipiv,work(n + 1),n, &
                              info)
                    do i = 1,n
                       work(n + i) = work(n + i)*work(i)
                    end do
                 else
                    ! multiply by inv(op(a))*diag(w).
                    do i = 1,n
                       work(n + i) = work(n + i)*work(i)
                    end do
                    call la_sgbtrs(trans,n,kl,ku,1,afb,ldafb,ipiv,work(n + 1),n, &
                              info)
                 end if
                 go to 100
              end if
              ! normalize error.
              lstres = zero
              do i = 1,n
                 lstres = max(lstres,abs(x(i,j)))
              end do
              if (lstres /= zero) ferr(j) = ferr(j)/lstres
           end do loop_140
           return
     end subroutine la_sgbrfs
     !> DGBRFS: improves the computed solution to a system of linear
     !> equations when the coefficient matrix is banded, and provides
     !> error bounds and backward error estimates for the solution.

     pure subroutine la_dgbrfs(trans,n,kl,ku,nrhs,ab,ldab,afb,ldafb,ipiv,b,ldb,x, &
               ldx,ferr,berr,work,iwork,info)
        use la_constants_dp,only:zero,one,two,three
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,ldafb,ldb,ldx,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(dp),intent(in) :: ab(ldab,*),afb(ldafb,*),b(ldb,*)
           real(dp),intent(out) :: berr(*),ferr(*),work(*)
           real(dp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           logical(lk) :: notran
           character :: transt
           integer(ilp) :: count,i,j,k,kase,kk,nz
           real(dp) :: eps,lstres,s,safe1,safe2,safmin,xk
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (nrhs < 0) then
              info = -5
           else if (ldab < kl + ku + 1) then
              info = -7
           else if (ldafb < 2*kl + ku + 1) then
              info = -9
           else if (ldb < max(1,n)) then
              info = -12
           else if (ldx < max(1,n)) then
              info = -14
           end if
           if (info /= 0) then
              call la_xerbla('DGBRFS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) then
              do j = 1,nrhs
                 ferr(j) = zero
                 berr(j) = zero
              end do
              return
           end if
           if (notran) then
              transt = 'T'
           else
              transt = 'N'
           end if
           ! nz = maximum number of nonzero elements in each row of a, plus 1
           nz = min(kl + ku + 2,n + 1)
           eps = la_dlamch('EPSILON')
           safmin = la_dlamch('SAFE MINIMUM')
           safe1 = nz*safmin
           safe2 = safe1/eps
           ! do for each right hand side
           loop_140: do j = 1,nrhs
              count = 1
              lstres = three
              20 continue
              ! loop until stopping criterion is satisfied.
              ! compute residual r = b - op(a) * x,
              ! where op(a) = a, a**t, or a**h, depending on trans.
              call la_dcopy(n,b(1,j),1,work(n + 1),1)
              call la_dgbmv(trans,n,n,kl,ku,-one,ab,ldab,x(1,j),1,one,work(n + 1 &
                        ),1)
              ! compute componentwise relative backward error from formula
              ! max(i) ( abs(r(i)) / ( abs(op(a))*abs(x) + abs(b) )(i) )
              ! where abs(z) is the componentwise absolute value of the matrix
              ! or vector z.  if the i-th component of the denominator is less
              ! than safe2, then safe1 is added to the i-th components of the
              ! numerator and denominator before dividing.
              do i = 1,n
                 work(i) = abs(b(i,j))
              end do
              ! compute abs(op(a))*abs(x) + abs(b).
              if (notran) then
                 do k = 1,n
                    kk = ku + 1 - k
                    xk = abs(x(k,j))
                    do i = max(1,k - ku),min(n,k + kl)
                       work(i) = work(i) + abs(ab(kk + i,k))*xk
                    end do
                 end do
              else
                 do k = 1,n
                    s = zero
                    kk = ku + 1 - k
                    do i = max(1,k - ku),min(n,k + kl)
                       s = s + abs(ab(kk + i,k))*abs(x(i,j))
                    end do
                    work(k) = work(k) + s
                 end do
              end if
              s = zero
              do i = 1,n
                 if (work(i) > safe2) then
                    s = max(s,abs(work(n + i))/work(i))
                 else
                    s = max(s, (abs(work(n + i)) + safe1)/(work(i) + safe1))
                 end if
              end do
              berr(j) = s
              ! test stopping criterion. continue iterating if
                 ! 1) the residual berr(j) is larger than machine epsilon, and
                 ! 2) berr(j) decreased by at least a factor of 2 during the
                    ! last iteration, and
                 ! 3) at most itmax iterations tried.
              if (berr(j) > eps .and. two*berr(j) <= lstres .and. count <= itmax) then
                 ! update solution and try again.
                 call la_dgbtrs(trans,n,kl,ku,1,afb,ldafb,ipiv,work(n + 1),n,info)

                 call la_daxpy(n,one,work(n + 1),1,x(1,j),1)
                 lstres = berr(j)
                 count = count + 1
                 go to 20
              end if
              ! bound error from formula
              ! norm(x - xtrue) / norm(x) .le. ferr =
              ! norm( abs(inv(op(a)))*
                 ! ( abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) ))) / norm(x)
              ! where
                ! norm(z) is the magnitude of the largest component of z
                ! inv(op(a)) is the inverse of op(a)
                ! abs(z) is the componentwise absolute value of the matrix or
                   ! vector z
                ! nz is the maximum number of nonzeros in any row of a, plus 1
                ! eps is machine epsilon
              ! the i-th component of abs(r)+nz*eps*(abs(op(a))*abs(x)+abs(b))
              ! is incremented by safe1 if the i-th component of
              ! abs(op(a))*abs(x) + abs(b) is less than safe2.
              ! use la_dlacn2 to estimate the infinity-norm of the matrix
                 ! inv(op(a)) * diag(w),
              ! where w = abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) )))
              do i = 1,n
                 if (work(i) > safe2) then
                    work(i) = abs(work(n + i)) + nz*eps*work(i)
                 else
                    work(i) = abs(work(n + i)) + nz*eps*work(i) + safe1
                 end if
              end do
              kase = 0
              100 continue
              call la_dlacn2(n,work(2*n + 1),work(n + 1),iwork,ferr(j),kase,isave)

              if (kase /= 0) then
                 if (kase == 1) then
                    ! multiply by diag(w)*inv(op(a)**t).
                    call la_dgbtrs(transt,n,kl,ku,1,afb,ldafb,ipiv,work(n + 1),n, &
                              info)
                    do i = 1,n
                       work(n + i) = work(n + i)*work(i)
                    end do
                 else
                    ! multiply by inv(op(a))*diag(w).
                    do i = 1,n
                       work(n + i) = work(n + i)*work(i)
                    end do
                    call la_dgbtrs(trans,n,kl,ku,1,afb,ldafb,ipiv,work(n + 1),n, &
                              info)
                 end if
                 go to 100
              end if
              ! normalize error.
              lstres = zero
              do i = 1,n
                 lstres = max(lstres,abs(x(i,j)))
              end do
              if (lstres /= zero) ferr(j) = ferr(j)/lstres
           end do loop_140
           return
     end subroutine la_dgbrfs
