                       if (jp /= 1) then
                          ! apply interchange to columns j to j+jb-1
                          if (jp + jj - 1 < j + kl) then
                             call la_dswap(jb,ab(kv + 1 + jj - j,j),ldab - 1,ab(kv + jp + jj - j,j) &
                                       ,ldab - 1)
                          else
                             ! the interchange affects columns j to jj-1 of a31
                             ! which are stored in the work array work31
                             call la_dswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,work31(jp + jj - j - &
                                       kl,1),ldwork)
                             call la_dswap(j + jb - jj,ab(kv + 1,jj),ldab - 1,ab(kv + jp,jj), &
