              ! ju is the index of the last column affected by the current
              ! stage of the factorization
              ju = 1
              loop_180: do j = 1,min(m,n),nb
                 jb = min(nb,min(m,n) - j + 1)
                 ! the active part of the matrix is partitioned
                    ! a11   a12   a13
                    ! a21   a22   a23
                    ! a31   a32   a33
                 ! here a11, a21 and a31 denote the current block of jb columns
                 ! which is about to be factorized. the number of rows in the
                 ! partitioning are jb, i2, i3 respectively, and the numbers
                 ! of columns are jb, j2, j3. the superdiagonal elements of a13
                 ! and the subdiagonal elements of a31 lie outside the band.
                 i2 = min(kl - jb,m - j - jb + 1)
                 i3 = min(jb,m - j - kl + 1)
                 ! j2 and j3 are computed after ju has been updated.
                 ! factorize the current block of jb columns
                 loop_80: do jj = j,j + jb - 1
                    ! set fill-in elements in column jj+kv to zero
                    if (jj + kv <= n) then
                       do i = 1,kl
                          ab(i,jj + kv) = zero
                       end do
                    end if
                    ! find pivot and test for singularity. km is the number of
                    ! subdiagonal elements in the current column.
                    km = min(kl,m - jj)
                    jp = la_ixamax(km + 1,ab(kv + 1,jj),1)
                    ipiv(jj) = jp + jj - j
                    if (ab(kv + jp,jj) /= zero) then
                       ju = max(ju,min(jj + ku + jp - 1,n))
                       if (jp /= 1) then
                          ! apply interchange to columns j to j+jb-1
                          if (jp + jj - 1 < j + kl) then
                             call la_xswap(jb,ab(kv + 1 + jj - j,j),ldab - 1,ab(kv + jp + jj - j,j) &
                                       ,ldab - 1)
                          else
                             ! the interchange affects columns j to jj-1 of a31
                             ! which are stored in the work array work31
                             call la_xswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,work31(jp + jj - j - &
                                       kl,1),ldwork)
                             call la_xswap(j + jb - jj,ab(kv + 1,jj),ldab - 1,ab(kv + jp,jj), &
                                       ldab - 1)
                          end if
                       end if
                       ! compute multipliers
                       call la_xscal(km,one/ab(kv + 1,jj),ab(kv + 2,jj),1)
                       ! update trailing submatrix within the band and within
                       ! the current block. jm is the index of the last column
                       ! which needs to be updated.
                       jm = min(ju,j + jb - 1)
                       if (jm > jj) call la_xger(km,jm - jj,-one,ab(kv + 2,jj),1,ab(kv,jj + &
                                 1),ldab - 1,ab(kv + 1,jj + 1),ldab - 1)
                    else
                       ! if pivot is zero, set info to the index of the pivot
                       ! unless a zero pivot has already been found.
                       if (info == 0) info = jj
                    end if
                    ! copy current column of a31 into the work array work31
                    nw = min(jj - j + 1,i3)
                    if (nw > 0) call la_xcopy(nw,ab(kv + kl + 1 - jj + j,jj),1,work31(1,jj - j + 1) &
                              ,1)
                 end do loop_80
                 if (j + jb <= n) then
                    ! apply the row interchanges to the other blocks.
                    j2 = min(ju - j + 1,kv) - jb
                    j3 = max(0,ju - j - kv + 1)
                    ! use la_xlaswp to apply the row interchanges to a12, a22, and
                    ! a32.
                    call la_xlaswp(j2,ab(kv + 1 - jb,j + jb),ldab - 1,1,jb,ipiv(j),1)

                    ! adjust the pivot indices.
                    do i = j,j + jb - 1
                       ipiv(i) = ipiv(i) + j - 1
                    end do
                    ! apply the row interchanges to a13, a23, and a33
                    ! columnwise.
                    k2 = j - 1 + jb + j2
                    do i = 1,j3
                       jj = k2 + i
                       do ii = j + i - 1,j + jb - 1
                          ip = ipiv(ii)
                          if (ip /= ii) then
                             temp = ab(kv + 1 + ii - jj,jj)
                             ab(kv + 1 + ii - jj,jj) = ab(kv + 1 + ip - jj,jj)
                             ab(kv + 1 + ip - jj,jj) = temp
                          end if
                       end do
                    end do
                    ! update the relevant part of the trailing submatrix
                    if (j2 > 0) then
                       ! update a12
                       call la_xtrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,j2,one,ab( &
                                  kv + 1,j),ldab - 1,ab(kv + 1 - jb,j + jb),ldab - 1)
                       if (i2 > 0) then
                          ! update a22
                          call la_xgemm('NO TRANSPOSE','NO TRANSPOSE',i2,j2,jb,-one,ab( &
                          kv + 1 + jb,j),ldab - 1,ab(kv + 1 - jb,j + jb),ldab - 1,one,ab(kv + 1,j + jb), &
                                    ldab - 1)
                       end if
                       if (i3 > 0) then
                          ! update a32
                          call la_xgemm('NO TRANSPOSE','NO TRANSPOSE',i3,j2,jb,-one, &
                          work31,ldwork,ab(kv + 1 - jb,j + jb),ldab - 1,one,ab(kv + kl + 1 - jb,j + jb), &
                                    ldab - 1)
                       end if
                    end if
                    if (j3 > 0) then
                       ! copy the lower triangle of a13 into the work array
                       ! work13
                       do jj = 1,j3
                          do ii = jj,jb
                             work13(ii,jj) = ab(ii - jj + 1,jj + j + kv - 1)
                          end do
                       end do
                       ! update a13 in the work array
                       call la_xtrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,j3,one,ab( &
                                  kv + 1,j),ldab - 1,work13,ldwork)
                       if (i2 > 0) then
                          ! update a23
                          call la_xgemm('NO TRANSPOSE','NO TRANSPOSE',i2,j3,jb,-one,ab( &
                          kv + 1 + jb,j),ldab - 1,work13,ldwork,one,ab(1 + jb,j + kv),ldab - 1)

                       end if
                       if (i3 > 0) then
                          ! update a33
                          call la_xgemm('NO TRANSPOSE','NO TRANSPOSE',i3,j3,jb,-one, &
                                    work31,ldwork,work13,ldwork,one,ab(1 + kl,j + kv),ldab - 1)
                       end if
                       ! copy the lower triangle of a13 back into place
                       do jj = 1,j3
                          do ii = jj,jb
                             ab(ii - jj + 1,jj + j + kv - 1) = work13(ii,jj)
                          end do
                       end do
                    end if
                 else
                    ! adjust the pivot indices.
                    do i = j,j + jb - 1
                       ipiv(i) = ipiv(i) + j - 1
                    end do
                 end if
                 ! partially undo the interchanges in the current block to
                 ! restore the upper triangular form of a31 and copy the upper
                 ! triangle of a31 back into place
                 do jj = j + jb - 1,j,-1
                    jp = ipiv(jj) - jj + 1
                    if (jp /= 1) then
                       ! apply interchange to columns j to jj-1
                       if (jp + jj - 1 < j + kl) then
                          ! the interchange does not affect a31
                          call la_xswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,ab(kv + jp + jj - j,j), &
                                     ldab - 1)
                       else
                          ! the interchange does affect a31
                          call la_xswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,work31(jp + jj - j - kl, &
                                    1),ldwork)
                       end if
                    end if
                    ! copy the current column of a31 back into place
                    nw = min(i3,jj - j + 1)
                    if (nw > 0) call la_xcopy(nw,work31(1,jj - j + 1),1,ab(kv + kl + 1 - jj + j,jj) &
                              ,1)
                 end do
              end do loop_180
           end if
           return
     end subroutine la_xgbtrf
#endif
#ifdef LA_WITH_QP
     !> QGBTRF: computes an LU factorization of a real m-by-n band matrix A
     !> using partial pivoting with row interchanges.
     !> This is the blocked version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_qgbtrf(m,n,kl,ku,ab,ldab,ipiv,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,m,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(qp),intent(inout) :: ab(ldab,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: nbmax = 64
           integer(ilp),parameter :: ldwork = nbmax + 1

           ! Local Scalars
           integer(ilp) :: i,i2,i3,ii,ip,j,j2,j3,jb,jj,jm,jp,ju,k2,km,kv,nb, &
                     nw
           real(qp) :: temp
           ! Local Arrays
           real(qp) :: work13(ldwork,nbmax),work31(ldwork,nbmax)
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! kv is the number of superdiagonals in the factor u, allowing for
           ! fill-in
           kv = ku + kl
           ! test the input parameters.
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (ldab < kl + kv + 1) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('QGBTRF',-info)
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) return
           ! determine the block size for this environment
           nb = la_ilaenv(1,'QGBTRF',' ',m,n,kl,ku)
           ! the block size must not exceed the limit set by the size of the
           ! local arrays work13 and work31.
           nb = min(nb,nbmax)
           if (nb <= 1 .or. nb > kl) then
              ! use unblocked code
              call la_qgbtf2(m,n,kl,ku,ab,ldab,ipiv,info)
           else
              ! use blocked code
              ! zero the superdiagonal elements of the work array work13
              do j = 1,nb
                 do i = 1,j - 1
                    work13(i,j) = zero
                 end do
              end do
              ! zero the subdiagonal elements of the work array work31
              do j = 1,nb
                 do i = j + 1,nb
                    work31(i,j) = zero
                 end do
              end do
              ! gaussian elimination with partial pivoting
              ! set fill-in elements in columns ku+2 to kv to zero
              do j = ku + 2,min(kv,n)
                 do i = kv - j + 2,kl
                    ab(i,j) = zero
                 end do
              end do
              ! ju is the index of the last column affected by the current
              ! stage of the factorization
              ju = 1
              loop_180: do j = 1,min(m,n),nb
                 jb = min(nb,min(m,n) - j + 1)
                 ! the active part of the matrix is partitioned
                    ! a11   a12   a13
                    ! a21   a22   a23
                    ! a31   a32   a33
                 ! here a11, a21 and a31 denote the current block of jb columns
                 ! which is about to be factorized. the number of rows in the
                 ! partitioning are jb, i2, i3 respectively, and the numbers
                 ! of columns are jb, j2, j3. the superdiagonal elements of a13
                 ! and the subdiagonal elements of a31 lie outside the band.
                 i2 = min(kl - jb,m - j - jb + 1)
                 i3 = min(jb,m - j - kl + 1)
                 ! j2 and j3 are computed after ju has been updated.
                 ! factorize the current block of jb columns
                 loop_80: do jj = j,j + jb - 1
                    ! set fill-in elements in column jj+kv to zero
                    if (jj + kv <= n) then
                       do i = 1,kl
                          ab(i,jj + kv) = zero
                       end do
                    end if
                    ! find pivot and test for singularity. km is the number of
                    ! subdiagonal elements in the current column.
                    km = min(kl,m - jj)
                    jp = la_iqamax(km + 1,ab(kv + 1,jj),1)
                    ipiv(jj) = jp + jj - j
                    if (ab(kv + jp,jj) /= zero) then
                       ju = max(ju,min(jj + ku + jp - 1,n))
                       if (jp /= 1) then
                          ! apply interchange to columns j to j+jb-1
                          if (jp + jj - 1 < j + kl) then
                             call la_qswap(jb,ab(kv + 1 + jj - j,j),ldab - 1,ab(kv + jp + jj - j,j) &
                                       ,ldab - 1)
                          else
                             ! the interchange affects columns j to jj-1 of a31
                             ! which are stored in the work array work31
                             call la_qswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,work31(jp + jj - j - &
                                       kl,1),ldwork)
                             call la_qswap(j + jb - jj,ab(kv + 1,jj),ldab - 1,ab(kv + jp,jj), &
                                       ldab - 1)
                          end if
                       end if
                       ! compute multipliers
                       call la_qscal(km,one/ab(kv + 1,jj),ab(kv + 2,jj),1)
                       ! update trailing submatrix within the band and within
                       ! the current block. jm is the index of the last column
                       ! which needs to be updated.
                       jm = min(ju,j + jb - 1)
                       if (jm > jj) call la_qger(km,jm - jj,-one,ab(kv + 2,jj),1,ab(kv,jj + &
                                 1),ldab - 1,ab(kv + 1,jj + 1),ldab - 1)
                    else
                       ! if pivot is zero, set info to the index of the pivot
                       ! unless a zero pivot has already been found.
                       if (info == 0) info = jj
                    end if
                    ! copy current column of a31 into the work array work31
                    nw = min(jj - j + 1,i3)
                    if (nw > 0) call la_qcopy(nw,ab(kv + kl + 1 - jj + j,jj),1,work31(1,jj - j + 1) &
                              ,1)
                 end do loop_80
                 if (j + jb <= n) then
                    ! apply the row interchanges to the other blocks.
                    j2 = min(ju - j + 1,kv) - jb
                    j3 = max(0,ju - j - kv + 1)
                    ! use la_qlaswp to apply the row interchanges to a12, a22, and
                    ! a32.
                    call la_qlaswp(j2,ab(kv + 1 - jb,j + jb),ldab - 1,1,jb,ipiv(j),1)

                    ! adjust the pivot indices.
                    do i = j,j + jb - 1
                       ipiv(i) = ipiv(i) + j - 1
                    end do
                    ! apply the row interchanges to a13, a23, and a33
                    ! columnwise.
                    k2 = j - 1 + jb + j2
                    do i = 1,j3
                       jj = k2 + i
                       do ii = j + i - 1,j + jb - 1
                          ip = ipiv(ii)
                          if (ip /= ii) then
                             temp = ab(kv + 1 + ii - jj,jj)
                             ab(kv + 1 + ii - jj,jj) = ab(kv + 1 + ip - jj,jj)
                             ab(kv + 1 + ip - jj,jj) = temp
                          end if
                       end do
                    end do
                    ! update the relevant part of the trailing submatrix
                    if (j2 > 0) then
                       ! update a12
                       call la_qtrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,j2,one,ab( &
                                  kv + 1,j),ldab - 1,ab(kv + 1 - jb,j + jb),ldab - 1)
                       if (i2 > 0) then
                          ! update a22
                          call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',i2,j2,jb,-one,ab( &
                          kv + 1 + jb,j),ldab - 1,ab(kv + 1 - jb,j + jb),ldab - 1,one,ab(kv + 1,j + jb), &
                                    ldab - 1)
                       end if
                       if (i3 > 0) then
                          ! update a32
                          call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',i3,j2,jb,-one, &
                          work31,ldwork,ab(kv + 1 - jb,j + jb),ldab - 1,one,ab(kv + kl + 1 - jb,j + jb), &
                                    ldab - 1)
                       end if
                    end if
                    if (j3 > 0) then
                       ! copy the lower triangle of a13 into the work array
                       ! work13
                       do jj = 1,j3
                          do ii = jj,jb
                             work13(ii,jj) = ab(ii - jj + 1,jj + j + kv - 1)
                          end do
                       end do
                       ! update a13 in the work array
                       call la_qtrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,j3,one,ab( &
                                  kv + 1,j),ldab - 1,work13,ldwork)
                       if (i2 > 0) then
                          ! update a23
                          call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',i2,j3,jb,-one,ab( &
                          kv + 1 + jb,j),ldab - 1,work13,ldwork,one,ab(1 + jb,j + kv),ldab - 1)

                       end if
                       if (i3 > 0) then
                          ! update a33
                          call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',i3,j3,jb,-one, &
                                    work31,ldwork,work13,ldwork,one,ab(1 + kl,j + kv),ldab - 1)
                       end if
                       ! copy the lower triangle of a13 back into place
                       do jj = 1,j3
                          do ii = jj,jb
                             ab(ii - jj + 1,jj + j + kv - 1) = work13(ii,jj)
                          end do
                       end do
                    end if
                 else
                    ! adjust the pivot indices.
                    do i = j,j + jb - 1
                       ipiv(i) = ipiv(i) + j - 1
                    end do
                 end if
                 ! partially undo the interchanges in the current block to
                 ! restore the upper triangular form of a31 and copy the upper
                 ! triangle of a31 back into place
                 do jj = j + jb - 1,j,-1
                    jp = ipiv(jj) - jj + 1
                    if (jp /= 1) then
                       ! apply interchange to columns j to jj-1
                       if (jp + jj - 1 < j + kl) then
                          ! the interchange does not affect a31
                          call la_qswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,ab(kv + jp + jj - j,j), &
                                     ldab - 1)
                       else
                          ! the interchange does affect a31
                          call la_qswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,work31(jp + jj - j - kl, &
                                    1),ldwork)
                       end if
                    end if
                    ! copy the current column of a31 back into place
                    nw = min(i3,jj - j + 1)
                    if (nw > 0) call la_qcopy(nw,work31(1,jj - j + 1),1,ab(kv + kl + 1 - jj + j,jj) &
                              ,1)
                 end do
              end do loop_180
           end if
           return
     end subroutine la_qgbtrf
#endif

     !> SGECON: estimates the reciprocal of the condition number of a general
     !> real matrix A, in either the 1-norm or the infinity-norm, using
     !> the LU factorization computed by SGETRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as
     !> RCOND = 1 / ( norm(A) * norm(inv(A)) ).

     pure subroutine la_sgecon(norm,n,a,lda,anorm,rcond,work,iwork,info)
        use la_constants_sp,only:zero,one
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: norm
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           real(sp),intent(in) :: anorm
           real(sp),intent(out) :: rcond
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: onenrm
           character :: normin
           integer(ilp) :: ix,kase,kase1
           real(sp) :: ainvnm,scale,sl,smlnum,su
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           onenrm = norm == '1' .or. la_lsame(norm,'O')
           if (.not. onenrm .and. .not. la_lsame(norm,'I')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (anorm < zero) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('SGECON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           smlnum = la_slamch('SAFE MINIMUM')
           ! estimate the norm of inv(a).
           ainvnm = zero
           normin = 'N'
           if (onenrm) then
              kase1 = 1
           else
              kase1 = 2
           end if
           kase = 0
           10 continue
           call la_slacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              if (kase == kase1) then
                 ! multiply by inv(l).
                 call la_slatrs('LOWER','NO TRANSPOSE','UNIT',normin,n,a,lda,work,sl, &
                           work(2*n + 1),info)
                 ! multiply by inv(u).
                 call la_slatrs('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,a,lda,work, &
                           su,work(3*n + 1),info)
              else
                 ! multiply by inv(u**t).
                 call la_slatrs('UPPER','TRANSPOSE','NON-UNIT',normin,n,a,lda,work,su, &
                            work(3*n + 1),info)
                 ! multiply by inv(l**t).
                 call la_slatrs('LOWER','TRANSPOSE','UNIT',normin,n,a,lda,work,sl, &
                           work(2*n + 1),info)
              end if
              ! divide x by 1/(sl*su) if doing so will not cause overflow.
              scale = sl*su
              normin = 'Y'
              if (scale /= one) then
                 ix = la_isamax(n,work,1)
                 if (scale < abs(work(ix))*smlnum .or. scale == zero) go to 20
                 call la_srscl(n,scale,work,1)
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           20 continue
           return
     end subroutine la_sgecon
     !> DGECON: estimates the reciprocal of the condition number of a general
     !> real matrix A, in either the 1-norm or the infinity-norm, using
     !> the LU factorization computed by DGETRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as
     !> RCOND = 1 / ( norm(A) * norm(inv(A)) ).

     pure subroutine la_dgecon(norm,n,a,lda,anorm,rcond,work,iwork,info)
        use la_constants_dp,only:zero,one
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: norm
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           real(dp),intent(in) :: anorm
           real(dp),intent(out) :: rcond
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(dp),intent(inout) :: a(lda,*)
           real(dp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: onenrm
           character :: normin
           integer(ilp) :: ix,kase,kase1
           real(dp) :: ainvnm,scale,sl,smlnum,su
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           onenrm = norm == '1' .or. la_lsame(norm,'O')
           if (.not. onenrm .and. .not. la_lsame(norm,'I')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (anorm < zero) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('DGECON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
