     !> SGESC2: solves a system of linear equations
     !> A * X = scale* RHS
     !> with a general N-by-N matrix A using the LU factorization with
     !> complete pivoting computed by SGETC2.

     pure subroutine la_sgesc2(n,a,lda,rhs,ipiv,jpiv,scale)
        use la_constants_sp,only:one,two
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: lda,n
           real(sp),intent(out) :: scale
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*),jpiv(*)
           real(sp),intent(in) :: a(lda,*)
           real(sp),intent(inout) :: rhs(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j
           real(sp) :: bignum,eps,smlnum,temp
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
            ! set constant to control overflow
           eps = la_slamch('P')
           smlnum = la_slamch('S')/eps
           bignum = one/smlnum
           call la_slabad(smlnum,bignum)
           ! apply permutations ipiv to rhs
           call la_slaswp(1,rhs,lda,1,n - 1,ipiv,1)
           ! solve for l part
           do i = 1,n - 1
              do j = i + 1,n
                 rhs(j) = rhs(j) - a(j,i)*rhs(i)
              end do
           end do
           ! solve for u part
           scale = one
           ! check for scaling
           i = la_isamax(n,rhs,1)
           if (two*smlnum*abs(rhs(i)) > abs(a(n,n))) then
              temp = (one/two)/abs(rhs(i))
              call la_sscal(n,temp,rhs(1),1)
              scale = scale*temp
           end if
           do i = n,1,-1
              temp = one/a(i,i)
              rhs(i) = rhs(i)*temp
              do j = i + 1,n
                 rhs(i) = rhs(i) - rhs(j)*(a(i,j)*temp)
              end do
           end do
           ! apply permutations jpiv to the solution (rhs)
           call la_slaswp(1,rhs,lda,1,n - 1,jpiv,-1)
           return
     end subroutine la_sgesc2
     !> DGESC2: solves a system of linear equations
     !> A * X = scale* RHS
     !> with a general N-by-N matrix A using the LU factorization with
     !> complete pivoting computed by DGETC2.

     pure subroutine la_dgesc2(n,a,lda,rhs,ipiv,jpiv,scale)
        use la_constants_dp,only:one,two
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: lda,n
           real(dp),intent(out) :: scale
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*),jpiv(*)
           real(dp),intent(in) :: a(lda,*)
           real(dp),intent(inout) :: rhs(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j
           real(dp) :: bignum,eps,smlnum,temp
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
            ! set constant to control overflow
           eps = la_dlamch('P')
           smlnum = la_dlamch('S')/eps
           bignum = one/smlnum
           call la_dlabad(smlnum,bignum)
           ! apply permutations ipiv to rhs
           call la_dlaswp(1,rhs,lda,1,n - 1,ipiv,1)
           ! solve for l part
           do i = 1,n - 1
              do j = i + 1,n
                 rhs(j) = rhs(j) - a(j,i)*rhs(i)
