           do i = n,1,-1
              temp = one/a(i,i)
              rhs(i) = rhs(i)*temp
              do j = i + 1,n
                 rhs(i) = rhs(i) - rhs(j)*(a(i,j)*temp)
              end do
           end do
           ! apply permutations jpiv to the solution (rhs)
           call la_dlaswp(1,rhs,lda,1,n - 1,jpiv,-1)
           return
