     !> SGETC2: computes an LU factorization with complete pivoting of the
     !> n-by-n matrix A. The factorization has the form A = P * L * U * Q,
     !> where P and Q are permutation matrices, L is lower triangular with
     !> unit diagonal elements and U is upper triangular.
     !> This is the Level 2 BLAS algorithm.

     pure subroutine la_sgetc2(n,a,lda,ipiv,jpiv,info)
        use la_constants_sp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*),jpiv(*)
           real(sp),intent(inout) :: a(lda,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,ip,ipv,j,jp,jpv
           real(sp) :: bignum,eps,smin,smlnum,xmax
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n == 0) return
           ! set constants to control overflow
           eps = la_slamch('P')
           smlnum = la_slamch('S')/eps
           bignum = one/smlnum
           call la_slabad(smlnum,bignum)
           ! handle the case n=1 by itself
           if (n == 1) then
              ipiv(1) = 1
              jpiv(1) = 1
              if (abs(a(1,1)) < smlnum) then
                 info = 1
                 a(1,1) = smlnum
              end if
              return
           end if
           ! factorize a using complete pivoting.
           ! set pivots less than smin to smin.
           loop_40: do i = 1,n - 1
              ! find max element in matrix a
              xmax = zero
              do ip = i,n
                 do jp = i,n
                    if (abs(a(ip,jp)) >= xmax) then
                       xmax = abs(a(ip,jp))
                       ipv = ip
                       jpv = jp
                    end if
                 end do
              end do
              if (i == 1) smin = max(eps*xmax,smlnum)
              ! swap rows
              if (ipv /= i) call la_sswap(n,a(ipv,1),lda,a(i,1),lda)
              ipiv(i) = ipv
              ! swap columns
              if (jpv /= i) call la_sswap(n,a(1,jpv),1,a(1,i),1)
              jpiv(i) = jpv
              ! check for singularity
              if (abs(a(i,i)) < smin) then
                 info = i
                 a(i,i) = smin
              end if
              do j = i + 1,n
                 a(j,i) = a(j,i)/a(i,i)
              end do
              call la_sger(n - i,n - i,-one,a(i + 1,i),1,a(i,i + 1),lda,a(i + 1,i + 1), &
                        lda)
           end do loop_40
           if (abs(a(n,n)) < smin) then
              info = n
              a(n,n) = smin
           end if
           ! set last pivots to n
           ipiv(n) = n
           jpiv(n) = n
           return
     end subroutine la_sgetc2
