              ! apply interchanges to [ --- ]
                                    ! [ a22 ]
              call la_slaswp(n2,a(1,n1 + 1),lda,1,n1,ipiv,1)
              ! solve a12
              call la_strsm('L','L','N','U',n1,n2,one,a,lda,a(1,n1 + 1),lda)

              ! update a22
              call la_sgemm('N','N',m - n1,n2,n1,-one,a(n1 + 1,1),lda,a(1,n1 + 1), &
                        lda,one,a(n1 + 1,n1 + 1),lda)
              ! factor a22
              call la_sgetrf2(m - n1,n2,a(n1 + 1,n1 + 1),lda,ipiv(n1 + 1),iinfo)
              ! adjust info and the pivot indices
              if (info == 0 .and. iinfo > 0) info = iinfo + n1
              do i = n1 + 1,min(m,n)
                 ipiv(i) = ipiv(i) + n1
              end do
              ! apply interchanges to a21
              call la_slaswp(n1,a(1,1),lda,n1 + 1,min(m,n),ipiv,1)
           end if
           return
