              call la_qgetrf2(m,n1,a,lda,ipiv,iinfo)
              if (info == 0 .and. iinfo > 0) info = iinfo
                                    ! [ a12 ]
              ! apply interchanges to [ --- ]
                                    ! [ a22 ]
              call la_qlaswp(n2,a(1,n1 + 1),lda,1,n1,ipiv,1)
              ! solve a12
              call la_qtrsm('L','L','N','U',n1,n2,one,a,lda,a(1,n1 + 1),lda)

              ! update a22
              call la_qgemm('N','N',m - n1,n2,n1,-one,a(n1 + 1,1),lda,a(1,n1 + 1), &
                        lda,one,a(n1 + 1,n1 + 1),lda)
              ! factor a22
              call la_qgetrf2(m - n1,n2,a(n1 + 1,n1 + 1),lda,ipiv(n1 + 1),iinfo)
              ! adjust info and the pivot indices
              if (info == 0 .and. iinfo > 0) info = iinfo + n1
              do i = n1 + 1,min(m,n)
                 ipiv(i) = ipiv(i) + n1
              end do
              ! apply interchanges to a21
              call la_qlaswp(n1,a(1,1),lda,n1 + 1,min(m,n),ipiv,1)
           end if
           return
     end subroutine la_qgetrf2
#endif

     !> SGETRI: computes the inverse of a matrix using the LU factorization
     !> computed by SGETRF.
     !> This method inverts U and then computes inv(A) by solving the system
     !> inv(A)*L = inv(U) for inv(A).

     pure subroutine la_sgetri(n,a,lda,ipiv,work,lwork,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,lwork,n
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: i,iws,j,jb,jj,jp,ldwork,lwkopt,nb,nbmin,nn
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           nb = la_ilaenv(1,'SGETRI',' ',n,-1,-1,-1)
           lwkopt = n*nb
           work(1) = lwkopt
           lquery = (lwork == -1)
           if (n < 0) then
              info = -1
           else if (lda < max(1,n)) then
              info = -3
           else if (lwork < max(1,n) .and. .not. lquery) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('SGETRI',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! form inv(u).  if info > 0 from la_strtri, then u is singular,
           ! and the inverse is not computed.
           call la_strtri('UPPER','NON-UNIT',n,a,lda,info)
           if (info > 0) return
           nbmin = 2
           ldwork = n
           if (nb > 1 .and. nb < n) then
              iws = max(ldwork*nb,1)
              if (lwork < iws) then
                 nb = lwork/ldwork
                 nbmin = max(2,la_ilaenv(2,'SGETRI',' ',n,-1,-1,-1))
              end if
           else
              iws = n
           end if
           ! solve the equation inv(a)*l = inv(u) for inv(a).
           if (nb < nbmin .or. nb >= n) then
              ! use unblocked code.
              do j = n,1,-1
                 ! copy current column of l to work and replace with zeros.
                 do i = j + 1,n
                    work(i) = a(i,j)
                    a(i,j) = zero
                 end do
                 ! compute current column of inv(a).
                 if (j < n) call la_sgemv('NO TRANSPOSE',n,n - j,-one,a(1,j + 1),lda,work( &
                           j + 1),1,one,a(1,j),1)
              end do
           else
              ! use blocked code.
              nn = ((n - 1)/nb)*nb + 1
              do j = nn,1,-nb
                 jb = min(nb,n - j + 1)
                 ! copy current block column of l to work and replace with
                 ! zeros.
                 do jj = j,j + jb - 1
                    do i = jj + 1,n
                       work(i + (jj - j)*ldwork) = a(i,jj)
                       a(i,jj) = zero
                    end do
                 end do
                 ! compute current block column of inv(a).
                 if (j + jb <= n) call la_sgemm('NO TRANSPOSE','NO TRANSPOSE',n,jb,n - j - jb + 1,- &
                           one,a(1,j + jb),lda,work(j + jb),ldwork,one,a(1,j),lda)
                 call la_strsm('RIGHT','LOWER','NO TRANSPOSE','UNIT',n,jb,one,work(j) &
                           ,ldwork,a(1,j),lda)
              end do
           end if
           ! apply column interchanges.
           do j = n - 1,1,-1
              jp = ipiv(j)
              if (jp /= j) call la_sswap(n,a(1,j),1,a(1,jp),1)
           end do
           work(1) = iws
           return
     end subroutine la_sgetri
