     !> SGETRS: solves a system of linear equations
     !> A * X = B  or  A**T * X = B
     !> with a general N-by-N matrix A using the LU factorization computed
     !> by SGETRF.

     pure subroutine la_sgetrs(trans,n,nrhs,a,lda,ipiv,b,ldb,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(sp),intent(in) :: a(lda,*)
           real(sp),intent(inout) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: notran
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('SGETRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           if (notran) then
              ! solve a * x = b.
              ! apply row interchanges to the right hand sides.
              call la_slaswp(nrhs,b,ldb,1,n,ipiv,1)
              ! solve l*x = b, overwriting b with x.
              call la_strsm('LEFT','LOWER','NO TRANSPOSE','UNIT',n,nrhs,one,a,lda,b, &
                        ldb)
              ! solve u*x = b, overwriting b with x.
              call la_strsm('LEFT','UPPER','NO TRANSPOSE','NON-UNIT',n,nrhs,one,a,lda, &
                         b,ldb)
           else
              ! solve a**t * x = b.
              ! solve u**t *x = b, overwriting b with x.
              call la_strsm('LEFT','UPPER','TRANSPOSE','NON-UNIT',n,nrhs,one,a,lda,b, &
                         ldb)
              ! solve l**t *x = b, overwriting b with x.
              call la_strsm('LEFT','LOWER','TRANSPOSE','UNIT',n,nrhs,one,a,lda,b, &
                        ldb)
              ! apply row interchanges to the solution vectors.
              call la_slaswp(nrhs,b,ldb,1,n,ipiv,-1)
           end if
           return
     end subroutine la_sgetrs
