           if (notran) then
              ! solve a * x = b.
              ! apply row interchanges to the right hand sides.
              call la_xlaswp(nrhs,b,ldb,1,n,ipiv,1)
              ! solve l*x = b, overwriting b with x.
              call la_xtrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',n,nrhs,one,a,lda,b, &
                        ldb)
              ! solve u*x = b, overwriting b with x.
              call la_xtrsm('LEFT','UPPER','NO TRANSPOSE','NON-UNIT',n,nrhs,one,a,lda, &
                         b,ldb)
           else
