                         ldb)
              ! solve l**t *x = b, overwriting b with x.
              call la_xtrsm('LEFT','LOWER','TRANSPOSE','UNIT',n,nrhs,one,a,lda,b, &
                        ldb)
              ! apply row interchanges to the solution vectors.
              call la_xlaswp(nrhs,b,ldb,1,n,ipiv,-1)
           end if
           return
     end subroutine la_xgetrs
