     !> SGTTRS: solves one of the systems of equations
     !> A*X = B  or  A**T*X = B,
     !> with a tridiagonal matrix A using the LU factorization computed
     !> by SGTTRF.

     pure subroutine la_sgttrs(trans,n,nrhs,dl,d,du,du2,ipiv,b,ldb,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(sp),intent(inout) :: b(ldb,*)
           real(sp),intent(in) :: d(*),dl(*),du(*),du2(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: notran
           integer(ilp) :: itrans,j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           info = 0
           notran = (trans == 'N' .or. trans == 'N')
           if (.not. notran .and. .not. (trans == 'T' .or. trans == 'T') .and. .not. (trans == 'C' .or. &
                     trans == 'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(n,1)) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('SGTTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           ! decode trans
           if (notran) then
              itrans = 0
           else
              itrans = 1
           end if
           ! determine the number of right-hand sides to solve at a time.
           if (nrhs == 1) then
              nb = 1
           else
              nb = max(1,la_ilaenv(1,'SGTTRS',trans,n,nrhs,-1,-1))
           end if
           if (nb >= nrhs) then
              call la_sgtts2(itrans,n,nrhs,dl,d,du,du2,ipiv,b,ldb)
           else
              do j = 1,nrhs,nb
                 jb = min(nrhs - j + 1,nb)
                 call la_sgtts2(itrans,n,jb,dl,d,du,du2,ipiv,b(1,j),ldb)
              end do
           end if
     end subroutine la_sgttrs
