     !> SLA_GBRCOND: Estimates the Skeel condition number of  op(A) * op2(C)
     !> where op2 is determined by CMODE as follows
     !> CMODE =  1    op2(C) = C
     !> CMODE =  0    op2(C) = I
     !> CMODE = -1    op2(C) = inv(C)
     !> The Skeel condition number  cond(A) = norminf( |inv(A)||A| )
     !> is computed by computing scaling factors R such that
     !> diag(R)*A*op2(C) is row equilibrated and computing the standard
     !> infinity-norm condition number.

     real(sp) function la_sla_gbrcond(trans,n,kl,ku,ab,ldab,afb,ldafb,ipiv,cmode,c, &
               info,work,iwork)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(in) :: n,ldab,ldafb,kl,ku,cmode
           integer(ilp),intent(out) :: info
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           integer(ilp),intent(in) :: ipiv(*)
           real(sp),intent(in) :: ab(ldab,*),afb(ldafb,*),c(*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: notrans
           integer(ilp) :: kase,i,j,kd,ke
           real(sp) :: ainvnm,tmp
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           la_sla_gbrcond = zero
           info = 0
           notrans = la_lsame(trans,'N')
           if (.not. notrans .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0 .or. kl > n - 1) then
              info = -3
           else if (ku < 0 .or. ku > n - 1) then
              info = -4
           else if (ldab < kl + ku + 1) then
              info = -6
           else if (ldafb < 2*kl + ku + 1) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('SLA_GBRCOND',-info)
              return
           end if
           if (n == 0) then
              la_sla_gbrcond = one
              return
           end if
           ! compute the equilibration matrix r such that
           ! inv(r)*a*c has unit 1-norm.
           kd = ku + 1
           ke = kl + 1
           if (notrans) then
              do i = 1,n
                 tmp = zero
                    if (cmode == 1) then
                       do j = max(i - kl,1),min(i + ku,n)
                          tmp = tmp + abs(ab(kd + i - j,j)*c(j))
                       end do
                    else if (cmode == 0) then
                       do j = max(i - kl,1),min(i + ku,n)
                          tmp = tmp + abs(ab(kd + i - j,j))
                       end do
                    else
                       do j = max(i - kl,1),min(i + ku,n)
                          tmp = tmp + abs(ab(kd + i - j,j)/c(j))
                       end do
                    end if
                 work(2*n + i) = tmp
              end do
           else
              do i = 1,n
                 tmp = zero
                 if (cmode == 1) then
                    do j = max(i - kl,1),min(i + ku,n)
                       tmp = tmp + abs(ab(ke - i + j,i)*c(j))
                    end do
                 else if (cmode == 0) then
                    do j = max(i - kl,1),min(i + ku,n)
                       tmp = tmp + abs(ab(ke - i + j,i))
                    end do
                 else
                    do j = max(i - kl,1),min(i + ku,n)
                       tmp = tmp + abs(ab(ke - i + j,i)/c(j))
                    end do
                 end if
                 work(2*n + i) = tmp
              end do
           end if
           ! estimate the norm of inv(op(a)).
           ainvnm = zero
           kase = 0
           10 continue
           call la_slacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              if (kase == 2) then
                 ! multiply by r.
                 do i = 1,n
                    work(i) = work(i)*work(2*n + i)
                 end do
                 if (notrans) then
                    call la_sgbtrs('NO TRANSPOSE',n,kl,ku,1,afb,ldafb,ipiv,work,n, &
                              info)
                 else
                    call la_sgbtrs('TRANSPOSE',n,kl,ku,1,afb,ldafb,ipiv,work,n,info &
                              )
                 end if
                 ! multiply by inv(c).
                 if (cmode == 1) then
                    do i = 1,n
                       work(i) = work(i)/c(i)
                    end do
                 else if (cmode == -1) then
                    do i = 1,n
                       work(i) = work(i)*c(i)
                    end do
                 end if
              else
                 ! multiply by inv(c**t).
                 if (cmode == 1) then
                    do i = 1,n
                       work(i) = work(i)/c(i)
                    end do
                 else if (cmode == -1) then
                    do i = 1,n
                       work(i) = work(i)*c(i)
                    end do
                 end if
                 if (notrans) then
                    call la_sgbtrs('TRANSPOSE',n,kl,ku,1,afb,ldafb,ipiv,work,n,info &
                              )
                 else
                    call la_sgbtrs('NO TRANSPOSE',n,kl,ku,1,afb,ldafb,ipiv,work,n, &
                              info)
                 end if
                 ! multiply by r.
                 do i = 1,n
                    work(i) = work(i)*work(2*n + i)
                 end do
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= 0.0_sp) la_sla_gbrcond = (1.0_sp/ainvnm)
           return
     end function la_sla_gbrcond
     !> DLA_GBRCOND: Estimates the Skeel condition number of  op(A) * op2(C)
     !> where op2 is determined by CMODE as follows
     !> CMODE =  1    op2(C) = C
     !> CMODE =  0    op2(C) = I
     !> CMODE = -1    op2(C) = inv(C)
     !> The Skeel condition number  cond(A) = norminf( |inv(A)||A| )
