                       work(i) = work(i)*c(i)
                    end do
                 end if
                 if (notrans) then
                    call la_dgetrs('TRANSPOSE',n,1,af,ldaf,ipiv,work,n,info)
                 else
                    call la_dgetrs('NO TRANSPOSE',n,1,af,ldaf,ipiv,work,n,info)

                 end if
                 ! multiply by r.
                 do i = 1,n
                    work(i) = work(i)*work(2*n + i)
                 end do
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) la_dla_gercond = (one/ainvnm)
           return
     end function la_dla_gercond
#ifdef LA_WITH_XDP
     !> XLA_GERCOND: estimates the Skeel condition number of op(A) * op2(C)
     !> where op2 is determined by CMODE as follows
     !> CMODE =  1    op2(C) = C
     !> CMODE =  0    op2(C) = I
     !> CMODE = -1    op2(C) = inv(C)
     !> The Skeel condition number cond(A) = norminf( |inv(A)||A| )
     !> is computed by computing scaling factors R such that
     !> diag(R)*A*op2(C) is row equilibrated and computing the standard
     !> infinity-norm condition number.

     real(xdp) function la_xla_gercond(trans,n,a,lda,af,ldaf,ipiv,cmode,c,info,work, &
               iwork)
        use la_constants_xdp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(in) :: n,lda,ldaf,cmode
           integer(ilp),intent(out) :: info
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(xdp),intent(in) :: a(lda,*),af(ldaf,*),c(*)
           real(xdp),intent(out) :: work(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: notrans
           integer(ilp) :: kase,i,j
           real(xdp) :: ainvnm,tmp
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           la_xla_gercond = zero
           info = 0
           notrans = la_lsame(trans,'N')
           if (.not. notrans .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (ldaf < max(1,n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('XLA_GERCOND',-info)
              return
           end if
           if (n == 0) then
              la_xla_gercond = one
              return
           end if
           ! compute the equilibration matrix r such that
           ! inv(r)*a*c has unit 1-norm.
           if (notrans) then
              do i = 1,n
                 tmp = zero
                 if (cmode == 1) then
                    do j = 1,n
                       tmp = tmp + abs(a(i,j)*c(j))
                    end do
                 else if (cmode == 0) then
                    do j = 1,n
                       tmp = tmp + abs(a(i,j))
                    end do
                 else
                    do j = 1,n
                       tmp = tmp + abs(a(i,j)/c(j))
                    end do
                 end if
                 work(2*n + i) = tmp
              end do
           else
              do i = 1,n
                 tmp = zero
                 if (cmode == 1) then
                    do j = 1,n
                       tmp = tmp + abs(a(j,i)*c(j))
                    end do
                 else if (cmode == 0) then
                    do j = 1,n
                       tmp = tmp + abs(a(j,i))
                    end do
                 else
                    do j = 1,n
                       tmp = tmp + abs(a(j,i)/c(j))
                    end do
                 end if
                 work(2*n + i) = tmp
              end do
           end if
           ! estimate the norm of inv(op(a)).
           ainvnm = zero
           kase = 0
           10 continue
           call la_xlacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              if (kase == 2) then
                 ! multiply by r.
                 do i = 1,n
                    work(i) = work(i)*work(2*n + i)
                 end do
                 if (notrans) then
                    call la_xgetrs('NO TRANSPOSE',n,1,af,ldaf,ipiv,work,n,info)

                 else
                    call la_xgetrs('TRANSPOSE',n,1,af,ldaf,ipiv,work,n,info)
                 end if
                 ! multiply by inv(c).
                 if (cmode == 1) then
                    do i = 1,n
                       work(i) = work(i)/c(i)
                    end do
                 else if (cmode == -1) then
                    do i = 1,n
                       work(i) = work(i)*c(i)
                    end do
                 end if
              else
                 ! multiply by inv(c**t).
                 if (cmode == 1) then
                    do i = 1,n
                       work(i) = work(i)/c(i)
                    end do
                 else if (cmode == -1) then
                    do i = 1,n
                       work(i) = work(i)*c(i)
                    end do
                 end if
                 if (notrans) then
                    call la_xgetrs('TRANSPOSE',n,1,af,ldaf,ipiv,work,n,info)
                 else
                    call la_xgetrs('NO TRANSPOSE',n,1,af,ldaf,ipiv,work,n,info)

                 end if
                 ! multiply by r.
                 do i = 1,n
                    work(i) = work(i)*work(2*n + i)
                 end do
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) la_xla_gercond = (one/ainvnm)
           return
     end function la_xla_gercond
#endif
