     !> SLATDF: uses the LU factorization of the n-by-n matrix Z computed by
     !> SGETC2 and computes a contribution to the reciprocal Dif-estimate
     !> by solving Z * x = b for x, and choosing the r.h.s. b such that
     !> the norm of x is as large as possible. On entry RHS = b holds the
     !> contribution from earlier solved sub-systems, and on return RHS = x.
     !> The factorization of Z returned by SGETC2 has the form Z = P*L*U*Q,
     !> where P and Q are permutation matrices. L is lower triangular with
     !> unit diagonal elements and U is upper triangular.

     pure subroutine la_slatdf(ijob,n,z,ldz,rhs,rdsum,rdscal,ipiv,jpiv)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ijob,ldz,n
           real(sp),intent(inout) :: rdscal,rdsum
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*),jpiv(*)
           real(sp),intent(inout) :: rhs(*),z(ldz,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: maxdim = 8

           ! Local Scalars
           integer(ilp) :: i,info,j,k
           real(sp) :: bm,bp,pmone,sminu,splus,temp
           ! Local Arrays
           integer(ilp) :: iwork(maxdim)
           real(sp) :: work(4*maxdim),xm(maxdim),xp(maxdim)
           ! Intrinsic Functions
           intrinsic :: abs,sqrt
           ! Executable Statements
           if (ijob /= 2) then
              ! apply permutations ipiv to rhs
              call la_slaswp(1,rhs,ldz,1,n - 1,ipiv,1)
              ! solve for l-part choosing rhs either to +1 or -1.
              pmone = -one
              loop_10: do j = 1,n - 1
                 bp = rhs(j) + one
                 bm = rhs(j) - one
                 splus = one
                 ! look-ahead for l-part rhs(1:n-1) = + or -1, splus and
                 ! smin computed more efficiently than in bsolve [1].
                 splus = splus + la_sdot(n - j,z(j + 1,j),1,z(j + 1,j),1)
                 sminu = la_sdot(n - j,z(j + 1,j),1,rhs(j + 1),1)
                 splus = splus*rhs(j)
                 if (splus > sminu) then
                    rhs(j) = bp
                 else if (sminu > splus) then
                    rhs(j) = bm
                 else
                    ! in this case the updating sums are equal and we can
                    ! choose rhs(j) +1 or -1. the first time this happens
                    ! we choose -1, thereafter +1. this is a simple way to
                    ! get good estimates of matrices like byers well-known
                    ! example (see [1]). (not done in bsolve.)
                    rhs(j) = rhs(j) + pmone
                    pmone = one
                 end if
                 ! compute the remaining r.h.s.
                 temp = -rhs(j)
                 call la_saxpy(n - j,temp,z(j + 1,j),1,rhs(j + 1),1)
              end do loop_10
              ! solve for u-part, look-ahead for rhs(n) = +-1. this is not done
              ! in bsolve and will hopefully give us a better estimate because
              ! any ill-conditioning of the original matrix is transferred to u
              ! and not to l. u(n, n) is an approximation to sigma_min(lu).
              call la_scopy(n - 1,rhs,1,xp,1)
              xp(n) = rhs(n) + one
              rhs(n) = rhs(n) - one
              splus = zero
              sminu = zero
              do i = n,1,-1
                 temp = one/z(i,i)
                 xp(i) = xp(i)*temp
                 rhs(i) = rhs(i)*temp
                 do k = i + 1,n
                    xp(i) = xp(i) - xp(k)*(z(i,k)*temp)
                    rhs(i) = rhs(i) - rhs(k)*(z(i,k)*temp)
                 end do
                 splus = splus + abs(xp(i))
                 sminu = sminu + abs(rhs(i))
              end do
              if (splus > sminu) call la_scopy(n,xp,1,rhs,1)
              ! apply the permutations jpiv to the computed solution (rhs)
              call la_slaswp(1,rhs,ldz,1,n - 1,jpiv,-1)
              ! compute the sum of squares
              call la_slassq(n,rhs,1,rdscal,rdsum)
           else
              ! ijob = 2, compute approximate nullvector xm of z
              call la_sgecon('I',n,z,ldz,one,temp,work,iwork,info)
              call la_scopy(n,work(n + 1),1,xm,1)
              ! compute rhs
              call la_slaswp(1,xm,ldz,1,n - 1,ipiv,-1)
              temp = one/sqrt(la_sdot(n,xm,1,xm,1))
              call la_sscal(n,temp,xm,1)
              call la_scopy(n,xm,1,xp,1)
              call la_saxpy(n,one,rhs,1,xp,1)
              call la_saxpy(n,-one,xm,1,rhs,1)
              call la_sgesc2(n,z,ldz,rhs,ipiv,jpiv,temp)
              call la_sgesc2(n,z,ldz,xp,ipiv,jpiv,temp)
              if (la_sasum(n,xp,1) > la_sasum(n,rhs,1)) call la_scopy(n,xp,1, &
                         rhs,1)
              ! compute the sum of squares
              call la_slassq(n,rhs,1,rdscal,rdsum)
           end if
           return
     end subroutine la_slatdf
     !> DLATDF: uses the LU factorization of the n-by-n matrix Z computed by
     !> DGETC2 and computes a contribution to the reciprocal Dif-estimate
     !> by solving Z * x = b for x, and choosing the r.h.s. b such that
     !> the norm of x is as large as possible. On entry RHS = b holds the
     !> contribution from earlier solved sub-systems, and on return RHS = x.
