                 splus = one
                 ! look-ahead for l-part rhs(1:n-1) = + or -1, splus and
                 ! smin computed more efficiently than in bsolve [1].
                 splus = splus + la_ddot(n - j,z(j + 1,j),1,z(j + 1,j),1)
                 sminu = la_ddot(n - j,z(j + 1,j),1,rhs(j + 1),1)
                 splus = splus*rhs(j)
                 if (splus > sminu) then
                    rhs(j) = bp
                 else if (sminu > splus) then
                    rhs(j) = bm
                 else
                    ! in this case the updating sums are equal and we can
                    ! choose rhs(j) +1 or -1. the first time this happens
                    ! we choose -1, thereafter +1. this is a simple way to
                    ! get good estimates of matrices like byers well-known
                    ! example (see [1]). (not done in bsolve.)
                    rhs(j) = rhs(j) + pmone
                    pmone = one
                 end if
                 ! compute the remaining r.h.s.
                 temp = -rhs(j)
                 call la_daxpy(n - j,temp,z(j + 1,j),1,rhs(j + 1),1)
              end do loop_10
              ! solve for u-part, look-ahead for rhs(n) = +-1. this is not done
              ! in bsolve and will hopefully give us a better estimate because
              ! any ill-conditioning of the original matrix is transferred to u
              ! and not to l. u(n, n) is an approximation to sigma_min(lu).
              call la_dcopy(n - 1,rhs,1,xp,1)
              xp(n) = rhs(n) + one
              rhs(n) = rhs(n) - one
              splus = zero
              sminu = zero
              do i = n,1,-1
                 temp = one/z(i,i)
                 xp(i) = xp(i)*temp
                 rhs(i) = rhs(i)*temp
                 do k = i + 1,n
                    xp(i) = xp(i) - xp(k)*(z(i,k)*temp)
                    rhs(i) = rhs(i) - rhs(k)*(z(i,k)*temp)
                 end do
                 splus = splus + abs(xp(i))
                 sminu = sminu + abs(rhs(i))
              end do
              if (splus > sminu) call la_dcopy(n,xp,1,rhs,1)
              ! apply the permutations jpiv to the computed solution (rhs)
              call la_dlaswp(1,rhs,ldz,1,n - 1,jpiv,-1)
              ! compute the sum of squares
              call la_dlassq(n,rhs,1,rdscal,rdsum)
           else
              ! ijob = 2, compute approximate nullvector xm of z
              call la_dgecon('I',n,z,ldz,one,temp,work,iwork,info)
              call la_dcopy(n,work(n + 1),1,xm,1)
              ! compute rhs
              call la_dlaswp(1,xm,ldz,1,n - 1,ipiv,-1)
              temp = one/sqrt(la_ddot(n,xm,1,xm,1))
              call la_dscal(n,temp,xm,1)
              call la_dcopy(n,xm,1,xp,1)
              call la_daxpy(n,one,rhs,1,xp,1)
              call la_daxpy(n,-one,xm,1,rhs,1)
              call la_dgesc2(n,z,ldz,rhs,ipiv,jpiv,temp)
              call la_dgesc2(n,z,ldz,xp,ipiv,jpiv,temp)
              if (la_dasum(n,xp,1) > la_dasum(n,rhs,1)) call la_dcopy(n,xp,1, &
                         rhs,1)
              ! compute the sum of squares
              call la_dlassq(n,rhs,1,rdscal,rdsum)
           end if
           return
     end subroutine la_dlatdf
#ifdef LA_WITH_XDP
