                 sminu = la_xdot(n - j,z(j + 1,j),1,rhs(j + 1),1)
                 splus = splus*rhs(j)
                 if (splus > sminu) then
                    rhs(j) = bp
                 else if (sminu > splus) then
                    rhs(j) = bm
                 else
                    ! in this case the updating sums are equal and we can
                    ! choose rhs(j) +1 or -1. the first time this happens
                    ! we choose -1, thereafter +1. this is a simple way to
                    ! get good estimates of matrices like byers well-known
                    ! example (see [1]). (not done in bsolve.)
                    rhs(j) = rhs(j) + pmone
                    pmone = one
                 end if
                 ! compute the remaining r.h.s.
                 temp = -rhs(j)
                 call la_xaxpy(n - j,temp,z(j + 1,j),1,rhs(j + 1),1)
              end do loop_10
              ! solve for u-part, look-ahead for rhs(n) = +-1. this is not done
              ! in bsolve and will hopefully give us a better estimate because
              ! any ill-conditioning of the original matrix is transferred to u
              ! and not to l. u(n, n) is an approximation to sigma_min(lu).
              call la_xcopy(n - 1,rhs,1,xp,1)
              xp(n) = rhs(n) + one
              rhs(n) = rhs(n) - one
              splus = zero
              sminu = zero
              do i = n,1,-1
                 temp = one/z(i,i)
                 xp(i) = xp(i)*temp
                 rhs(i) = rhs(i)*temp
                 do k = i + 1,n
                    xp(i) = xp(i) - xp(k)*(z(i,k)*temp)
                    rhs(i) = rhs(i) - rhs(k)*(z(i,k)*temp)
                 end do
                 splus = splus + abs(xp(i))
                 sminu = sminu + abs(rhs(i))
              end do
              if (splus > sminu) call la_xcopy(n,xp,1,rhs,1)
              ! apply the permutations jpiv to the computed solution (rhs)
              call la_xlaswp(1,rhs,ldz,1,n - 1,jpiv,-1)
              ! compute the sum of squares
              call la_xlassq(n,rhs,1,rdscal,rdsum)
           else
              ! ijob = 2, compute approximate nullvector xm of z
              call la_xgecon('I',n,z,ldz,one,temp,work,iwork,info)
              call la_xcopy(n,work(n + 1),1,xm,1)
              ! compute rhs
              call la_xlaswp(1,xm,ldz,1,n - 1,ipiv,-1)
              temp = one/sqrt(la_xdot(n,xm,1,xm,1))
              call la_xscal(n,temp,xm,1)
              call la_xcopy(n,xm,1,xp,1)
              call la_xaxpy(n,one,rhs,1,xp,1)
              call la_xaxpy(n,-one,xm,1,rhs,1)
              call la_xgesc2(n,z,ldz,rhs,ipiv,jpiv,temp)
              call la_xgesc2(n,z,ldz,xp,ipiv,jpiv,temp)
              if (la_xasum(n,xp,1) > la_xasum(n,rhs,1)) call la_xcopy(n,xp,1, &
                         rhs,1)
              ! compute the sum of squares
              call la_xlassq(n,rhs,1,rdscal,rdsum)
           end if
           return
     end subroutine la_xlatdf
#endif
#ifdef LA_WITH_QP
     !> QLATDF: uses the LU factorization of the n-by-n matrix Z computed by
     !> QGETC2 and computes a contribution to the reciprocal Dif-estimate
     !> by solving Z * x = b for x, and choosing the r.h.s. b such that
     !> the norm of x is as large as possible. On entry RHS = b holds the
     !> contribution from earlier solved sub-systems, and on return RHS = x.
     !> The factorization of Z returned by QGETC2 has the form Z = P*L*U*Q,
     !> where P and Q are permutation matrices. L is lower triangular with
     !> unit diagonal elements and U is upper triangular.

     pure subroutine la_qlatdf(ijob,n,z,ldz,rhs,rdsum,rdscal,ipiv,jpiv)
        use la_constants_qp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ijob,ldz,n
           real(qp),intent(inout) :: rdscal,rdsum
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*),jpiv(*)
           real(qp),intent(inout) :: rhs(*),z(ldz,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: maxdim = 8

           ! Local Scalars
           integer(ilp) :: i,info,j,k
           real(qp) :: bm,bp,pmone,sminu,splus,temp
           ! Local Arrays
           integer(ilp) :: iwork(maxdim)
           real(qp) :: work(4*maxdim),xm(maxdim),xp(maxdim)
           ! Intrinsic Functions
           intrinsic :: abs,sqrt
           ! Executable Statements
           if (ijob /= 2) then
              ! apply permutations ipiv to rhs
              call la_qlaswp(1,rhs,ldz,1,n - 1,ipiv,1)
              ! solve for l-part choosing rhs either to +1 or -1.
              pmone = -one
              loop_10: do j = 1,n - 1
                 bp = rhs(j) + one
                 bm = rhs(j) - one
                 splus = one
                 ! look-ahead for l-part rhs(1:n-1) = + or -1, splus and
                 ! smin computed more efficiently than in bsolve [1].
                 splus = splus + la_qdot(n - j,z(j + 1,j),1,z(j + 1,j),1)
                 sminu = la_qdot(n - j,z(j + 1,j),1,rhs(j + 1),1)
                 splus = splus*rhs(j)
                 if (splus > sminu) then
                    rhs(j) = bp
                 else if (sminu > splus) then
                    rhs(j) = bm
                 else
                    ! in this case the updating sums are equal and we can
                    ! choose rhs(j) +1 or -1. the first time this happens
                    ! we choose -1, thereafter +1. this is a simple way to
                    ! get good estimates of matrices like byers well-known
                    ! example (see [1]). (not done in bsolve.)
                    rhs(j) = rhs(j) + pmone
                    pmone = one
                 end if
                 ! compute the remaining r.h.s.
                 temp = -rhs(j)
                 call la_qaxpy(n - j,temp,z(j + 1,j),1,rhs(j + 1),1)
              end do loop_10
              ! solve for u-part, look-ahead for rhs(n) = +-1. this is not done
              ! in bsolve and will hopefully give us a better estimate because
              ! any ill-conditioning of the original matrix is transferred to u
              ! and not to l. u(n, n) is an approximation to sigma_min(lu).
              call la_qcopy(n - 1,rhs,1,xp,1)
              xp(n) = rhs(n) + one
              rhs(n) = rhs(n) - one
              splus = zero
              sminu = zero
              do i = n,1,-1
                 temp = one/z(i,i)
                 xp(i) = xp(i)*temp
                 rhs(i) = rhs(i)*temp
                 do k = i + 1,n
                    xp(i) = xp(i) - xp(k)*(z(i,k)*temp)
                    rhs(i) = rhs(i) - rhs(k)*(z(i,k)*temp)
                 end do
                 splus = splus + abs(xp(i))
                 sminu = sminu + abs(rhs(i))
              end do
              if (splus > sminu) call la_qcopy(n,xp,1,rhs,1)
              ! apply the permutations jpiv to the computed solution (rhs)
              call la_qlaswp(1,rhs,ldz,1,n - 1,jpiv,-1)
              ! compute the sum of squares
              call la_qlassq(n,rhs,1,rdscal,rdsum)
           else
              ! ijob = 2, compute approximate nullvector xm of z
              call la_qgecon('I',n,z,ldz,one,temp,work,iwork,info)
              call la_qcopy(n,work(n + 1),1,xm,1)
              ! compute rhs
              call la_qlaswp(1,xm,ldz,1,n - 1,ipiv,-1)
              temp = one/sqrt(la_qdot(n,xm,1,xm,1))
              call la_qscal(n,temp,xm,1)
              call la_qcopy(n,xm,1,xp,1)
              call la_qaxpy(n,one,rhs,1,xp,1)
              call la_qaxpy(n,-one,xm,1,rhs,1)
              call la_qgesc2(n,z,ldz,rhs,ipiv,jpiv,temp)
              call la_qgesc2(n,z,ldz,xp,ipiv,jpiv,temp)
              if (la_qasum(n,xp,1) > la_qasum(n,rhs,1)) call la_qcopy(n,xp,1, &
                         rhs,1)
              ! compute the sum of squares
              call la_qlassq(n,rhs,1,rdscal,rdsum)
           end if
           return
     end subroutine la_qlatdf
#endif

     !> SGERFS: improves the computed solution to a system of linear
     !> equations and provides error bounds and backward error estimates for
     !> the solution.

     pure subroutine la_sgerfs(trans,n,nrhs,a,lda,af,ldaf,ipiv,b,ldb,x,ldx,ferr, &
               berr,work,iwork,info)
        use la_constants_sp,only:zero,one,two,three
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldaf,ldb,ldx,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(sp),intent(in) :: a(lda,*),af(ldaf,*),b(ldb,*)
           real(sp),intent(out) :: berr(*),ferr(*),work(*)
           real(sp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           logical(lk) :: notran
           character :: transt
           integer(ilp) :: count,i,j,k,kase,nz
           real(sp) :: eps,lstres,s,safe1,safe2,safmin,xk
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldaf < max(1,n)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -10
           else if (ldx < max(1,n)) then
              info = -12
           end if
           if (info /= 0) then
              call la_xerbla('SGERFS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) then
              do j = 1,nrhs
                 ferr(j) = zero
                 berr(j) = zero
              end do
              return
           end if
           if (notran) then
              transt = 'T'
           else
              transt = 'N'
           end if
           ! nz = maximum number of nonzero elements in each row of a, plus 1
           nz = n + 1
           eps = la_slamch('EPSILON')
           safmin = la_slamch('SAFE MINIMUM')
           safe1 = nz*safmin
           safe2 = safe1/eps
           ! do for each right hand side
           loop_140: do j = 1,nrhs
              count = 1
              lstres = three
              20 continue
              ! loop until stopping criterion is satisfied.
              ! compute residual r = b - op(a) * x,
              ! where op(a) = a, a**t, or a**h, depending on trans.
              call la_scopy(n,b(1,j),1,work(n + 1),1)
              call la_sgemv(trans,n,n,-one,a,lda,x(1,j),1,one,work(n + 1),1)

              ! compute componentwise relative backward error from formula
              ! max(i) ( abs(r(i)) / ( abs(op(a))*abs(x) + abs(b) )(i) )
              ! where abs(z) is the componentwise absolute value of the matrix
              ! or vector z.  if the i-th component of the denominator is less
              ! than safe2, then safe1 is added to the i-th components of the
              ! numerator and denominator before dividing.
              do i = 1,n
                 work(i) = abs(b(i,j))
              end do
              ! compute abs(op(a))*abs(x) + abs(b).
              if (notran) then
                 do k = 1,n
                    xk = abs(x(k,j))
                    do i = 1,n
                       work(i) = work(i) + abs(a(i,k))*xk
                    end do
                 end do
              else
                 do k = 1,n
                    s = zero
                    do i = 1,n
                       s = s + abs(a(i,k))*abs(x(i,j))
                    end do
                    work(k) = work(k) + s
                 end do
              end if
              s = zero
              do i = 1,n
                 if (work(i) > safe2) then
                    s = max(s,abs(work(n + i))/work(i))
                 else
                    s = max(s, (abs(work(n + i)) + safe1)/(work(i) + safe1))
                 end if
              end do
              berr(j) = s
              ! test stopping criterion. continue iterating if
                 ! 1) the residual berr(j) is larger than machine epsilon, and
                 ! 2) berr(j) decreased by at least a factor of 2 during the
                    ! last iteration, and
                 ! 3) at most itmax iterations tried.
              if (berr(j) > eps .and. two*berr(j) <= lstres .and. count <= itmax) then
                 ! update solution and try again.
                 call la_sgetrs(trans,n,1,af,ldaf,ipiv,work(n + 1),n,info)
                 call la_saxpy(n,one,work(n + 1),1,x(1,j),1)
                 lstres = berr(j)
                 count = count + 1
                 go to 20
              end if
              ! bound error from formula
              ! norm(x - xtrue) / norm(x) .le. ferr =
              ! norm( abs(inv(op(a)))*
                 ! ( abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) ))) / norm(x)
              ! where
                ! norm(z) is the magnitude of the largest component of z
                ! inv(op(a)) is the inverse of op(a)
                ! abs(z) is the componentwise absolute value of the matrix or
                   ! vector z
                ! nz is the maximum number of nonzeros in any row of a, plus 1
                ! eps is machine epsilon
              ! the i-th component of abs(r)+nz*eps*(abs(op(a))*abs(x)+abs(b))
              ! is incremented by safe1 if the i-th component of
              ! abs(op(a))*abs(x) + abs(b) is less than safe2.
              ! use la_slacn2 to estimate the infinity-norm of the matrix
                 ! inv(op(a)) * diag(w),
              ! where w = abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) )))
              do i = 1,n
                 if (work(i) > safe2) then
                    work(i) = abs(work(n + i)) + nz*eps*work(i)
                 else
                    work(i) = abs(work(n + i)) + nz*eps*work(i) + safe1
                 end if
              end do
              kase = 0
              100 continue
              call la_slacn2(n,work(2*n + 1),work(n + 1),iwork,ferr(j),kase,isave)

              if (kase /= 0) then
                 if (kase == 1) then
                    ! multiply by diag(w)*inv(op(a)**t).
                    call la_sgetrs(transt,n,1,af,ldaf,ipiv,work(n + 1),n,info)

                    do i = 1,n
                       work(n + i) = work(i)*work(n + i)
                    end do
                 else
                    ! multiply by inv(op(a))*diag(w).
                    do i = 1,n
                       work(n + i) = work(i)*work(n + i)
                    end do
                    call la_sgetrs(trans,n,1,af,ldaf,ipiv,work(n + 1),n,info)
                 end if
                 go to 100
              end if
              ! normalize error.
              lstres = zero
              do i = 1,n
                 lstres = max(lstres,abs(x(i,j)))
              end do
              if (lstres /= zero) ferr(j) = ferr(j)/lstres
           end do loop_140
           return
     end subroutine la_sgerfs
     !> DGERFS: improves the computed solution to a system of linear
     !> equations and provides error bounds and backward error estimates for
     !> the solution.

     pure subroutine la_dgerfs(trans,n,nrhs,a,lda,af,ldaf,ipiv,b,ldb,x,ldx,ferr, &
               berr,work,iwork,info)
        use la_constants_dp,only:zero,one,two,three
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldaf,ldb,ldx,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(dp),intent(in) :: a(lda,*),af(ldaf,*),b(ldb,*)
           real(dp),intent(out) :: berr(*),ferr(*),work(*)
           real(dp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           logical(lk) :: notran
           character :: transt
           integer(ilp) :: count,i,j,k,kase,nz
           real(dp) :: eps,lstres,s,safe1,safe2,safmin,xk
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
