     !> SGETRF: computes an LU factorization of a general M-by-N matrix A
     !> using partial pivoting with row interchanges.
     !> The factorization has the form
     !> A = P * L * U
     !> where P is a permutation matrix, L is lower triangular with unit
     !> diagonal elements (lower trapezoidal if m > n), and U is upper
     !> triangular (upper trapezoidal if m < n).
     !> This is the right-looking Level 3 BLAS version of the algorithm.

     pure subroutine la_sgetrf(m,n,a,lda,ipiv,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(sp),intent(inout) :: a(lda,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,iinfo,j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('SGETRF',-info)
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) return
           ! determine the block size for this environment.
           nb = la_ilaenv(1,'SGETRF',' ',m,n,-1,-1)
           if (nb <= 1 .or. nb >= min(m,n)) then
              ! use unblocked code.
              call la_sgetrf2(m,n,a,lda,ipiv,info)
           else
              ! use blocked code.
              do j = 1,min(m,n),nb
                 jb = min(min(m,n) - j + 1,nb)
                 ! factor diagonal and subdiagonal blocks and test for exact
                 ! singularity.
                 call la_sgetrf2(m - j + 1,jb,a(j,j),lda,ipiv(j),iinfo)
                 ! adjust info and the pivot indices.
                 if (info == 0 .and. iinfo > 0) info = iinfo + j - 1
                 do i = j,min(m,j + jb - 1)
                    ipiv(i) = j - 1 + ipiv(i)
                 end do
                 ! apply interchanges to columns 1:j-1.
                 call la_slaswp(j - 1,a,lda,j,j + jb - 1,ipiv,1)
                 if (j + jb <= n) then
                    ! apply interchanges to columns j+jb:n.
                    call la_slaswp(n - j - jb + 1,a(1,j + jb),lda,j,j + jb - 1,ipiv,1)
                    ! compute block row of u.
                    call la_strsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,n - j - jb + 1,one, &
                              a(j,j),lda,a(j,j + jb),lda)
                    if (j + jb <= m) then
                       ! update trailing submatrix.
                       call la_sgemm('NO TRANSPOSE','NO TRANSPOSE',m - j - jb + 1,n - j - jb + 1,jb,- &
                       one,a(j + jb,j),lda,a(j,j + jb),lda,one,a(j + jb,j + jb),lda)

                    end if
                 end if
              end do
           end if
           return
     end subroutine la_sgetrf
     !> DGETRF: computes an LU factorization of a general M-by-N matrix A
     !> using partial pivoting with row interchanges.
     !> The factorization has the form
     !> A = P * L * U
     !> where P is a permutation matrix, L is lower triangular with unit
     !> diagonal elements (lower trapezoidal if m > n), and U is upper
     !> triangular (upper trapezoidal if m < n).
     !> This is the right-looking Level 3 BLAS version of the algorithm.

     pure subroutine la_dgetrf(m,n,a,lda,ipiv,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(dp),intent(inout) :: a(lda,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,iinfo,j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('DGETRF',-info)
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) return
           ! determine the block size for this environment.
           nb = la_ilaenv(1,'DGETRF',' ',m,n,-1,-1)
           if (nb <= 1 .or. nb >= min(m,n)) then
              ! use unblocked code.
              call la_dgetrf2(m,n,a,lda,ipiv,info)
           else
              ! use blocked code.
              do j = 1,min(m,n),nb
                 jb = min(min(m,n) - j + 1,nb)
                 ! factor diagonal and subdiagonal blocks and test for exact
                 ! singularity.
                 call la_dgetrf2(m - j + 1,jb,a(j,j),lda,ipiv(j),iinfo)
                 ! adjust info and the pivot indices.
                 if (info == 0 .and. iinfo > 0) info = iinfo + j - 1
                 do i = j,min(m,j + jb - 1)
                    ipiv(i) = j - 1 + ipiv(i)
                 end do
                 ! apply interchanges to columns 1:j-1.
                 call la_dlaswp(j - 1,a,lda,j,j + jb - 1,ipiv,1)
                 if (j + jb <= n) then
                    ! apply interchanges to columns j+jb:n.
                    call la_dlaswp(n - j - jb + 1,a(1,j + jb),lda,j,j + jb - 1,ipiv,1)
                    ! compute block row of u.
                    call la_dtrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,n - j - jb + 1,one, &
                              a(j,j),lda,a(j,j + jb),lda)
                    if (j + jb <= m) then
                       ! update trailing submatrix.
                       call la_dgemm('NO TRANSPOSE','NO TRANSPOSE',m - j - jb + 1,n - j - jb + 1,jb,- &
                       one,a(j + jb,j),lda,a(j,j + jb),lda,one,a(j + jb,j + jb),lda)

                    end if
                 end if
              end do
           end if
           return
     end subroutine la_dgetrf
