     !> SGTRFS: improves the computed solution to a system of linear
     !> equations when the coefficient matrix is tridiagonal, and provides
     !> error bounds and backward error estimates for the solution.

     pure subroutine la_sgtrfs(trans,n,nrhs,dl,d,du,dlf,df,duf,du2,ipiv,b,ldb,x, &
               ldx,ferr,berr,work,iwork,info)
        use la_constants_sp,only:zero,one,two,three
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,ldx,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(sp),intent(in) :: b(ldb,*),d(*),df(*),dl(*),dlf(*),du(*),du2(*),duf(*)

           real(sp),intent(out) :: berr(*),ferr(*),work(*)
           real(sp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           logical(lk) :: notran
           character :: transn,transt
           integer(ilp) :: count,i,j,kase,nz
           real(sp) :: eps,lstres,s,safe1,safe2,safmin
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(1,n)) then
              info = -13
           else if (ldx < max(1,n)) then
              info = -15
           end if
           if (info /= 0) then
              call la_xerbla('SGTRFS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) then
              do j = 1,nrhs
                 ferr(j) = zero
                 berr(j) = zero
              end do
              return
           end if
           if (notran) then
              transn = 'N'
              transt = 'T'
           else
              transn = 'T'
              transt = 'N'
           end if
           ! nz = maximum number of nonzero elements in each row of a, plus 1
           nz = 4
           eps = la_slamch('EPSILON')
           safmin = la_slamch('SAFE MINIMUM')
           safe1 = nz*safmin
           safe2 = safe1/eps
           ! do for each right hand side
           loop_110: do j = 1,nrhs
              count = 1
              lstres = three
              20 continue
              ! loop until stopping criterion is satisfied.
              ! compute residual r = b - op(a) * x,
              ! where op(a) = a, a**t, or a**h, depending on trans.
              call la_scopy(n,b(1,j),1,work(n + 1),1)
              call la_slagtm(trans,n,1,-one,dl,d,du,x(1,j),ldx,one,work(n + 1), &
                        n)
              ! compute abs(op(a))*abs(x) + abs(b) for use in the backward
              ! error bound.
              if (notran) then
                 if (n == 1) then
                    work(1) = abs(b(1,j)) + abs(d(1)*x(1,j))
                 else
                    work(1) = abs(b(1,j)) + abs(d(1)*x(1,j)) + abs(du(1)*x(2,j) &
                               )
                    do i = 2,n - 1
                       work(i) = abs(b(i,j)) + abs(dl(i - 1)*x(i - 1,j)) + abs(d(i)*x( &
                                 i,j)) + abs(du(i)*x(i + 1,j))
                    end do
                    work(n) = abs(b(n,j)) + abs(dl(n - 1)*x(n - 1,j)) + abs(d(n)*x(n, &
                              j))
                 end if
              else
                 if (n == 1) then
                    work(1) = abs(b(1,j)) + abs(d(1)*x(1,j))
                 else
                    work(1) = abs(b(1,j)) + abs(d(1)*x(1,j)) + abs(dl(1)*x(2,j) &
                               )
                    do i = 2,n - 1
                       work(i) = abs(b(i,j)) + abs(du(i - 1)*x(i - 1,j)) + abs(d(i)*x( &
                                 i,j)) + abs(dl(i)*x(i + 1,j))
                    end do
                    work(n) = abs(b(n,j)) + abs(du(n - 1)*x(n - 1,j)) + abs(d(n)*x(n, &
                              j))
                 end if
              end if
              ! compute componentwise relative backward error from formula
              ! max(i) ( abs(r(i)) / ( abs(op(a))*abs(x) + abs(b) )(i) )
              ! where abs(z) is the componentwise absolute value of the matrix
              ! or vector z.  if the i-th component of the denominator is less
              ! than safe2, then safe1 is added to the i-th components of the
              ! numerator and denominator before dividing.
              s = zero
              do i = 1,n
                 if (work(i) > safe2) then
                    s = max(s,abs(work(n + i))/work(i))
                 else
                    s = max(s, (abs(work(n + i)) + safe1)/(work(i) + safe1))
                 end if
              end do
              berr(j) = s
              ! test stopping criterion. continue iterating if
                 ! 1) the residual berr(j) is larger than machine epsilon, and
                 ! 2) berr(j) decreased by at least a factor of 2 during the
                    ! last iteration, and
                 ! 3) at most itmax iterations tried.
              if (berr(j) > eps .and. two*berr(j) <= lstres .and. count <= itmax) then
                 ! update solution and try again.
                 call la_sgttrs(trans,n,1,dlf,df,duf,du2,ipiv,work(n + 1),n,info)

                 call la_saxpy(n,one,work(n + 1),1,x(1,j),1)
                 lstres = berr(j)
                 count = count + 1
                 go to 20
              end if
              ! bound error from formula
              ! norm(x - xtrue) / norm(x) .le. ferr =
              ! norm( abs(inv(op(a)))*
                 ! ( abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) ))) / norm(x)
              ! where
                ! norm(z) is the magnitude of the largest component of z
                ! inv(op(a)) is the inverse of op(a)
                ! abs(z) is the componentwise absolute value of the matrix or
                   ! vector z
                ! nz is the maximum number of nonzeros in any row of a, plus 1
                ! eps is machine epsilon
              ! the i-th component of abs(r)+nz*eps*(abs(op(a))*abs(x)+abs(b))
              ! is incremented by safe1 if the i-th component of
              ! abs(op(a))*abs(x) + abs(b) is less than safe2.
              ! use la_slacn2 to estimate the infinity-norm of the matrix
                 ! inv(op(a)) * diag(w),
              ! where w = abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) )))
              do i = 1,n
                 if (work(i) > safe2) then
                    work(i) = abs(work(n + i)) + nz*eps*work(i)
                 else
                    work(i) = abs(work(n + i)) + nz*eps*work(i) + safe1
                 end if
              end do
              kase = 0
              70 continue
              call la_slacn2(n,work(2*n + 1),work(n + 1),iwork,ferr(j),kase,isave)

              if (kase /= 0) then
                 if (kase == 1) then
                    ! multiply by diag(w)*inv(op(a)**t).
                    call la_sgttrs(transt,n,1,dlf,df,duf,du2,ipiv,work(n + 1),n, &
                              info)
                    do i = 1,n
                       work(n + i) = work(i)*work(n + i)
                    end do
                 else
                    ! multiply by inv(op(a))*diag(w).
                    do i = 1,n
                       work(n + i) = work(i)*work(n + i)
                    end do
                    call la_sgttrs(transn,n,1,dlf,df,duf,du2,ipiv,work(n + 1),n, &
                              info)
                 end if
                 go to 70
              end if
              ! normalize error.
              lstres = zero
              do i = 1,n
                 lstres = max(lstres,abs(x(i,j)))
              end do
              if (lstres /= zero) ferr(j) = ferr(j)/lstres
           end do loop_110
           return
     end subroutine la_sgtrfs
     !> DGTRFS: improves the computed solution to a system of linear
     !> equations when the coefficient matrix is tridiagonal, and provides
     !> error bounds and backward error estimates for the solution.

     pure subroutine la_dgtrfs(trans,n,nrhs,dl,d,du,dlf,df,duf,du2,ipiv,b,ldb,x, &
               ldx,ferr,berr,work,iwork,info)
        use la_constants_dp,only:zero,one,two,three
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,ldx,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(dp),intent(in) :: b(ldb,*),d(*),df(*),dl(*),dlf(*),du(*),du2(*),duf(*)

           real(dp),intent(out) :: berr(*),ferr(*),work(*)
           real(dp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           logical(lk) :: notran
           character :: transn,transt
           integer(ilp) :: count,i,j,kase,nz
           real(dp) :: eps,lstres,s,safe1,safe2,safmin
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(1,n)) then
              info = -13
           else if (ldx < max(1,n)) then
              info = -15
           end if
           if (info /= 0) then
              call la_xerbla('DGTRFS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) then
              do j = 1,nrhs
                 ferr(j) = zero
                 berr(j) = zero
              end do
              return
           end if
           if (notran) then
              transn = 'N'
              transt = 'T'
           else
              transn = 'T'
              transt = 'N'
           end if
           ! nz = maximum number of nonzero elements in each row of a, plus 1
           nz = 4
           eps = la_dlamch('EPSILON')
           safmin = la_dlamch('SAFE MINIMUM')
           safe1 = nz*safmin
           safe2 = safe1/eps
           ! do for each right hand side
           loop_110: do j = 1,nrhs
              count = 1
              lstres = three
              20 continue
              ! loop until stopping criterion is satisfied.
              ! compute residual r = b - op(a) * x,
              ! where op(a) = a, a**t, or a**h, depending on trans.
              call la_dcopy(n,b(1,j),1,work(n + 1),1)
              call la_dlagtm(trans,n,1,-one,dl,d,du,x(1,j),ldx,one,work(n + 1), &
                        n)
              ! compute abs(op(a))*abs(x) + abs(b) for use in the backward
              ! error bound.
              if (notran) then
                 if (n == 1) then
                    work(1) = abs(b(1,j)) + abs(d(1)*x(1,j))
                 else
                    work(1) = abs(b(1,j)) + abs(d(1)*x(1,j)) + abs(du(1)*x(2,j) &
                               )
                    do i = 2,n - 1
                       work(i) = abs(b(i,j)) + abs(dl(i - 1)*x(i - 1,j)) + abs(d(i)*x( &
                                 i,j)) + abs(du(i)*x(i + 1,j))
                    end do
                    work(n) = abs(b(n,j)) + abs(dl(n - 1)*x(n - 1,j)) + abs(d(n)*x(n, &
                              j))
                 end if
              else
                 if (n == 1) then
                    work(1) = abs(b(1,j)) + abs(d(1)*x(1,j))
                 else
                    work(1) = abs(b(1,j)) + abs(d(1)*x(1,j)) + abs(dl(1)*x(2,j) &
                               )
                    do i = 2,n - 1
                       work(i) = abs(b(i,j)) + abs(du(i - 1)*x(i - 1,j)) + abs(d(i)*x( &
                                 i,j)) + abs(dl(i)*x(i + 1,j))
                    end do
                    work(n) = abs(b(n,j)) + abs(du(n - 1)*x(n - 1,j)) + abs(d(n)*x(n, &
                              j))
                 end if
              end if
              ! compute componentwise relative backward error from formula
              ! max(i) ( abs(r(i)) / ( abs(op(a))*abs(x) + abs(b) )(i) )
              ! where abs(z) is the componentwise absolute value of the matrix
              ! or vector z.  if the i-th component of the denominator is less
              ! than safe2, then safe1 is added to the i-th components of the
              ! numerator and denominator before dividing.
              s = zero
              do i = 1,n
                 if (work(i) > safe2) then
                    s = max(s,abs(work(n + i))/work(i))
                 else
                    s = max(s, (abs(work(n + i)) + safe1)/(work(i) + safe1))
                 end if
              end do
              berr(j) = s
              ! test stopping criterion. continue iterating if
                 ! 1) the residual berr(j) is larger than machine epsilon, and
                 ! 2) berr(j) decreased by at least a factor of 2 during the
                    ! last iteration, and
                 ! 3) at most itmax iterations tried.
              if (berr(j) > eps .and. two*berr(j) <= lstres .and. count <= itmax) then
                 ! update solution and try again.
                 call la_dgttrs(trans,n,1,dlf,df,duf,du2,ipiv,work(n + 1),n,info)

                 call la_daxpy(n,one,work(n + 1),1,x(1,j),1)
                 lstres = berr(j)
                 count = count + 1
                 go to 20
              end if
              ! bound error from formula
              ! norm(x - xtrue) / norm(x) .le. ferr =
              ! norm( abs(inv(op(a)))*
                 ! ( abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) ))) / norm(x)
              ! where
                ! norm(z) is the magnitude of the largest component of z
                ! inv(op(a)) is the inverse of op(a)
                ! abs(z) is the componentwise absolute value of the matrix or
                   ! vector z
                ! nz is the maximum number of nonzeros in any row of a, plus 1
                ! eps is machine epsilon
              ! the i-th component of abs(r)+nz*eps*(abs(op(a))*abs(x)+abs(b))
              ! is incremented by safe1 if the i-th component of
              ! abs(op(a))*abs(x) + abs(b) is less than safe2.
              ! use la_dlacn2 to estimate the infinity-norm of the matrix
                 ! inv(op(a)) * diag(w),
              ! where w = abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) )))
              do i = 1,n
                 if (work(i) > safe2) then
                    work(i) = abs(work(n + i)) + nz*eps*work(i)
                 else
                    work(i) = abs(work(n + i)) + nz*eps*work(i) + safe1
                 end if
              end do
              kase = 0
              70 continue
              call la_dlacn2(n,work(2*n + 1),work(n + 1),iwork,ferr(j),kase,isave)

              if (kase /= 0) then
                 if (kase == 1) then
                    ! multiply by diag(w)*inv(op(a)**t).
                    call la_dgttrs(transt,n,1,dlf,df,duf,du2,ipiv,work(n + 1),n, &
                              info)
                    do i = 1,n
                       work(n + i) = work(i)*work(n + i)
                    end do
                 else
                    ! multiply by inv(op(a))*diag(w).
                    do i = 1,n
                       work(n + i) = work(i)*work(n + i)
                    end do
                    call la_dgttrs(transn,n,1,dlf,df,duf,du2,ipiv,work(n + 1),n, &
                              info)
                 end if
                 go to 70
              end if
              ! normalize error.
              lstres = zero
              do i = 1,n
                 lstres = max(lstres,abs(x(i,j)))
              end do
              if (lstres /= zero) ferr(j) = ferr(j)/lstres
           end do loop_110
           return
     end subroutine la_dgtrfs
