     !> CGBTF2: computes an LU factorization of a complex m-by-n band matrix
     !> A using partial pivoting with row interchanges.
     !> This is the unblocked version of the algorithm, calling Level 2 BLAS.

     pure subroutine la_cgbtf2(m,n,kl,ku,ab,ldab,ipiv,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,m,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(sp),intent(inout) :: ab(ldab,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j,jp,ju,km,kv
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! kv is the number of superdiagonals in the factor u, allowing for
           ! fill-in.
           kv = ku + kl
           ! test the input parameters.
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (ldab < kl + kv + 1) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('CGBTF2',-info)
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) return
           ! gaussian elimination with partial pivoting
           ! set fill-in elements in columns ku+2 to kv to czero.
           do j = ku + 2,min(kv,n)
              do i = kv - j + 2,kl
                 ab(i,j) = czero
              end do
           end do
           ! ju is the index of the last column affected by the current stage
           ! of the factorization.
           ju = 1
           loop_40: do j = 1,min(m,n)
              ! set fill-in elements in column j+kv to czero.
              if (j + kv <= n) then
                 do i = 1,kl
                    ab(i,j + kv) = czero
                 end do
              end if
              ! find pivot and test for singularity. km is the number of
              ! subdiagonal elements in the current column.
              km = min(kl,m - j)
              jp = la_icamax(km + 1,ab(kv + 1,j),1)
              ipiv(j) = jp + j - 1
              if (ab(kv + jp,j) /= czero) then
                 ju = max(ju,min(j + ku + jp - 1,n))
                 ! apply interchange to columns j to ju.
                 if (jp /= 1) call la_cswap(ju - j + 1,ab(kv + jp,j),ldab - 1,ab(kv + 1,j),ldab - &
                           1)
                 if (km > 0) then
                    ! compute multipliers.
                    call la_cscal(km,cone/ab(kv + 1,j),ab(kv + 2,j),1)
                    ! update trailing submatrix within the band.
                    if (ju > j) call la_cgeru(km,ju - j,-cone,ab(kv + 2,j),1,ab(kv,j + 1), &
                              ldab - 1,ab(kv + 1,j + 1),ldab - 1)
                 end if
              else
                 ! if pivot is czero, set info to the index of the pivot
                 ! unless a czero pivot has already been found.
                 if (info == 0) info = j
              end if
           end do loop_40
           return
     end subroutine la_cgbtf2
