        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*),jpiv(*)
           complex(dp),intent(inout) :: a(lda,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,ip,ipv,j,jp,jpv
           real(dp) :: bignum,eps,smin,smlnum,xmax
           ! Intrinsic Functions
           intrinsic :: abs,cmplx,max
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n == 0) return
           ! set constants to control overflow
           eps = la_dlamch('P')
           smlnum = la_dlamch('S')/eps
           bignum = one/smlnum
           call la_dlabad(smlnum,bignum)
           ! handle the case n=1 by itself
           if (n == 1) then
              ipiv(1) = 1
              jpiv(1) = 1
              if (abs(a(1,1)) < smlnum) then
                 info = 1
                 a(1,1) = cmplx(smlnum,zero,KIND=dp)
              end if
              return
           end if
           ! factorize a using complete pivoting.
           ! set pivots less than smin to smin
           loop_40: do i = 1,n - 1
              ! find max element in matrix a
              xmax = zero
              do ip = i,n
                 do jp = i,n
                    if (abs(a(ip,jp)) >= xmax) then
                       xmax = abs(a(ip,jp))
                       ipv = ip
                       jpv = jp
                    end if
                 end do
              end do
              if (i == 1) smin = max(eps*xmax,smlnum)
              ! swap rows
              if (ipv /= i) call la_zswap(n,a(ipv,1),lda,a(i,1),lda)
              ipiv(i) = ipv
              ! swap columns
              if (jpv /= i) call la_zswap(n,a(1,jpv),1,a(1,i),1)
              jpiv(i) = jpv
              ! check for singularity
              if (abs(a(i,i)) < smin) then
                 info = i
                 a(i,i) = cmplx(smin,zero,KIND=dp)
              end if
              do j = i + 1,n
                 a(j,i) = a(j,i)/a(i,i)
              end do
              call la_zgeru(n - i,n - i,-cmplx(one,KIND=dp),a(i + 1,i),1,a(i,i + 1),lda, &
                        a(i + 1,i + 1),lda)
           end do loop_40
           if (abs(a(n,n)) < smin) then
              info = n
              a(n,n) = cmplx(smin,zero,KIND=dp)
           end if
           ! set last pivots to n
           ipiv(n) = n
           jpiv(n) = n
           return
     end subroutine la_zgetc2
