     !> CGBCON: estimates the reciprocal of the condition number of a complex
     !> general band matrix A, in either the 1-norm or the infinity-norm,
     !> using the LU factorization computed by CGBTRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as
     !> RCOND = 1 / ( norm(A) * norm(inv(A)) ).

     pure subroutine la_cgbcon(norm,n,kl,ku,ab,ldab,ipiv,anorm,rcond,work,rwork, &
               info)
        use la_constants_sp,only:zero,one
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: norm
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,n
           real(sp),intent(in) :: anorm
           real(sp),intent(out) :: rcond
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(sp),intent(out) :: rwork(*)
           complex(sp),intent(in) :: ab(ldab,*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lnoti,onenrm
           character :: normin
           integer(ilp) :: ix,j,jp,kase,kase1,kd,lm
           real(sp) :: ainvnm,scale,smlnum
           complex(sp) :: t,zdum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,aimag,min,real
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(zdum) = abs(real(zdum,KIND=sp)) + abs(aimag(zdum))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           onenrm = norm == '1' .or. la_lsame(norm,'O')
           if (.not. onenrm .and. .not. la_lsame(norm,'I')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (ldab < 2*kl + ku + 1) then
              info = -6
           else if (anorm < zero) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('CGBCON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           smlnum = la_slamch('SAFE MINIMUM')
           ! estimate the norm of inv(a).
           ainvnm = zero
           normin = 'N'
           if (onenrm) then
              kase1 = 1
           else
              kase1 = 2
           end if
           kd = kl + ku + 1
           lnoti = kl > 0
           kase = 0
           10 continue
           call la_clacn2(n,work(n + 1),work,ainvnm,kase,isave)
           if (kase /= 0) then
              if (kase == kase1) then
                 ! multiply by inv(l).
                 if (lnoti) then
                    do j = 1,n - 1
                       lm = min(kl,n - j)
                       jp = ipiv(j)
                       t = work(jp)
                       if (jp /= j) then
                          work(jp) = work(j)
                          work(j) = t
                       end if
                       call la_caxpy(lm,-t,ab(kd + 1,j),1,work(j + 1),1)
                    end do
                 end if
                 ! multiply by inv(u).
                 call la_clatbs('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,kl + ku,ab, &
                           ldab,work,scale,rwork,info)
              else
                 ! multiply by inv(u**h).
                 call la_clatbs('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',normin,n,kl + ku, &
                           ab,ldab,work,scale,rwork,info)
                 ! multiply by inv(l**h).
                 if (lnoti) then
                    do j = n - 1,1,-1
                       lm = min(kl,n - j)
                       work(j) = work(j) - la_cdotc(lm,ab(kd + 1,j),1,work(j + 1),1)

                       jp = ipiv(j)
                       if (jp /= j) then
                          t = work(jp)
                          work(jp) = work(j)
                          work(j) = t
                       end if
                    end do
                 end if
              end if
              ! divide x by 1/scale if doing so will not cause overflow.
              normin = 'Y'
              if (scale /= one) then
                 ix = la_icamax(n,work,1)
                 if (scale < cabs1(work(ix))*smlnum .or. scale == zero) go to 40
                 call la_csrscl(n,scale,work,1)
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           40 continue
           return
     end subroutine la_cgbcon
