                    end do
                    ! apply the row interchanges to a13, a23, and a33
                    ! columnwise.
                    k2 = j - 1 + jb + j2
                    do i = 1,j3
                       jj = k2 + i
                       do ii = j + i - 1,j + jb - 1
                          ip = ipiv(ii)
