                 i2 = min(kl - jb,m - j - jb + 1)
                 i3 = min(jb,m - j - kl + 1)
                 ! j2 and j3 are computed after ju has been updated.
                 ! factorize the current block of jb columns
                 loop_80: do jj = j,j + jb - 1
                    ! set fill-in elements in column jj+kv to czero
                    if (jj + kv <= n) then
                       do i = 1,kl
                          ab(i,jj + kv) = czero
                       end do
                    end if
                    ! find pivot and test for singularity. km is the number of
                    ! subdiagonal elements in the current column.
                    km = min(kl,m - jj)
                    jp = la_iyamax(km + 1,ab(kv + 1,jj),1)
                    ipiv(jj) = jp + jj - j
                    if (ab(kv + jp,jj) /= czero) then
                       ju = max(ju,min(jj + ku + jp - 1,n))
                       if (jp /= 1) then
                          ! apply interchange to columns j to j+jb-1
                          if (jp + jj - 1 < j + kl) then
                             call la_yswap(jb,ab(kv + 1 + jj - j,j),ldab - 1,ab(kv + jp + jj - j,j) &
                                       ,ldab - 1)
                          else
                             ! the interchange affects columns j to jj-1 of a31
                             ! which are stored in the work array work31
                             call la_yswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,work31(jp + jj - j - &
                                       kl,1),ldwork)
                             call la_yswap(j + jb - jj,ab(kv + 1,jj),ldab - 1,ab(kv + jp,jj), &
                                       ldab - 1)
                          end if
                       end if
                       ! compute multipliers
                       call la_yscal(km,cone/ab(kv + 1,jj),ab(kv + 2,jj),1)
                       ! update trailing submatrix within the band and within
                       ! the current block. jm is the index of the last column
                       ! which needs to be updated.
                       jm = min(ju,j + jb - 1)
                       if (jm > jj) call la_ygeru(km,jm - jj,-cone,ab(kv + 2,jj),1,ab(kv, &
                                 jj + 1),ldab - 1,ab(kv + 1,jj + 1),ldab - 1)
                    else
                       ! if pivot is czero, set info to the index of the pivot
                       ! unless a czero pivot has already been found.
                       if (info == 0) info = jj
                    end if
                    ! copy current column of a31 into the work array work31
                    nw = min(jj - j + 1,i3)
                    if (nw > 0) call la_ycopy(nw,ab(kv + kl + 1 - jj + j,jj),1,work31(1,jj - j + 1) &
                              ,1)
                 end do loop_80
                 if (j + jb <= n) then
                    ! apply the row interchanges to the other blocks.
                    j2 = min(ju - j + 1,kv) - jb
                    j3 = max(0,ju - j - kv + 1)
                    ! use la_ylaswp to apply the row interchanges to a12, a22, and
                    ! a32.
                    call la_ylaswp(j2,ab(kv + 1 - jb,j + jb),ldab - 1,1,jb,ipiv(j),1)

                    ! adjust the pivot indices.
                    do i = j,j + jb - 1
                       ipiv(i) = ipiv(i) + j - 1
                    end do
                    ! apply the row interchanges to a13, a23, and a33
                    ! columnwise.
                    k2 = j - 1 + jb + j2
                    do i = 1,j3
                       jj = k2 + i
                       do ii = j + i - 1,j + jb - 1
                          ip = ipiv(ii)
                          if (ip /= ii) then
                             temp = ab(kv + 1 + ii - jj,jj)
                             ab(kv + 1 + ii - jj,jj) = ab(kv + 1 + ip - jj,jj)
                             ab(kv + 1 + ip - jj,jj) = temp
                          end if
                       end do
                    end do
                    ! update the relevant part of the trailing submatrix
                    if (j2 > 0) then
                       ! update a12
                       call la_ytrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,j2,cone, &
                                 ab(kv + 1,j),ldab - 1,ab(kv + 1 - jb,j + jb),ldab - 1)
                       if (i2 > 0) then
                          ! update a22
                          call la_ygemm('NO TRANSPOSE','NO TRANSPOSE',i2,j2,jb,-cone,ab( &
                           kv + 1 + jb,j),ldab - 1,ab(kv + 1 - jb,j + jb),ldab - 1,cone,ab(kv + 1,j + jb) &
                                     ,ldab - 1)
                       end if
                       if (i3 > 0) then
                          ! update a32
                          call la_ygemm('NO TRANSPOSE','NO TRANSPOSE',i3,j2,jb,-cone, &
                          work31,ldwork,ab(kv + 1 - jb,j + jb),ldab - 1,cone,ab(kv + kl + 1 - jb,j + jb), &
                                     ldab - 1)
                       end if
                    end if
                    if (j3 > 0) then
                       ! copy the lower triangle of a13 into the work array
                       ! work13
                       do jj = 1,j3
                          do ii = jj,jb
                             work13(ii,jj) = ab(ii - jj + 1,jj + j + kv - 1)
                          end do
                       end do
                       ! update a13 in the work array
                       call la_ytrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,j3,cone, &
                                 ab(kv + 1,j),ldab - 1,work13,ldwork)
                       if (i2 > 0) then
                          ! update a23
                          call la_ygemm('NO TRANSPOSE','NO TRANSPOSE',i2,j3,jb,-cone,ab( &
                           kv + 1 + jb,j),ldab - 1,work13,ldwork,cone,ab(1 + jb,j + kv),ldab - 1)

                       end if
                       if (i3 > 0) then
                          ! update a33
                          call la_ygemm('NO TRANSPOSE','NO TRANSPOSE',i3,j3,jb,-cone, &
                                    work31,ldwork,work13,ldwork,cone,ab(1 + kl,j + kv),ldab - 1)
                       end if
                       ! copy the lower triangle of a13 back into place
                       do jj = 1,j3
                          do ii = jj,jb
                             ab(ii - jj + 1,jj + j + kv - 1) = work13(ii,jj)
                          end do
                       end do
                    end if
                 else
                    ! adjust the pivot indices.
                    do i = j,j + jb - 1
                       ipiv(i) = ipiv(i) + j - 1
                    end do
                 end if
                 ! partially undo the interchanges in the current block to
                 ! restore the upper triangular form of a31 and copy the upper
                 ! triangle of a31 back into place
                 do jj = j + jb - 1,j,-1
                    jp = ipiv(jj) - jj + 1
                    if (jp /= 1) then
                       ! apply interchange to columns j to jj-1
                       if (jp + jj - 1 < j + kl) then
                          ! the interchange does not affect a31
                          call la_yswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,ab(kv + jp + jj - j,j), &
                                     ldab - 1)
                       else
                          ! the interchange does affect a31
                          call la_yswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,work31(jp + jj - j - kl, &
                                    1),ldwork)
                       end if
                    end if
                    ! copy the current column of a31 back into place
                    nw = min(i3,jj - j + 1)
                    if (nw > 0) call la_ycopy(nw,work31(1,jj - j + 1),1,ab(kv + kl + 1 - jj + j,jj) &
                              ,1)
                 end do
              end do loop_180
           end if
           return
     end subroutine la_ygbtrf
#endif
#ifdef LA_WITH_QP
     !> WGBTRF: computes an LU factorization of a complex m-by-n band matrix A
     !> using partial pivoting with row interchanges.
     !> This is the blocked version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_wgbtrf(m,n,kl,ku,ab,ldab,ipiv,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,m,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(qp),intent(inout) :: ab(ldab,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: nbmax = 64
           integer(ilp),parameter :: ldwork = nbmax + 1

           ! Local Scalars
           integer(ilp) :: i,i2,i3,ii,ip,j,j2,j3,jb,jj,jm,jp,ju,k2,km,kv,nb, &
                     nw
           complex(qp) :: temp
           ! Local Arrays
           complex(qp) :: work13(ldwork,nbmax),work31(ldwork,nbmax)
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! kv is the number of superdiagonals in the factor u, allowing for
           ! fill-in
           kv = ku + kl
           ! test the input parameters.
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (ldab < kl + kv + 1) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('WGBTRF',-info)
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) return
           ! determine the block size for this environment
           nb = la_ilaenv(1,'WGBTRF',' ',m,n,kl,ku)
           ! the block size must not exceed the limit set by the size of the
           ! local arrays work13 and work31.
           nb = min(nb,nbmax)
           if (nb <= 1 .or. nb > kl) then
              ! use unblocked code
              call la_wgbtf2(m,n,kl,ku,ab,ldab,ipiv,info)
           else
              ! use blocked code
              ! czero the superdiagonal elements of the work array work13
              do j = 1,nb
                 do i = 1,j - 1
                    work13(i,j) = czero
                 end do
              end do
              ! czero the subdiagonal elements of the work array work31
              do j = 1,nb
                 do i = j + 1,nb
                    work31(i,j) = czero
                 end do
              end do
              ! gaussian elimination with partial pivoting
              ! set fill-in elements in columns ku+2 to kv to czero
              do j = ku + 2,min(kv,n)
                 do i = kv - j + 2,kl
                    ab(i,j) = czero
                 end do
              end do
              ! ju is the index of the last column affected by the current
              ! stage of the factorization
              ju = 1
              loop_180: do j = 1,min(m,n),nb
                 jb = min(nb,min(m,n) - j + 1)
                 ! the active part of the matrix is partitioned
                    ! a11   a12   a13
                    ! a21   a22   a23
                    ! a31   a32   a33
                 ! here a11, a21 and a31 denote the current block of jb columns
                 ! which is about to be factorized. the number of rows in the
                 ! partitioning are jb, i2, i3 respectively, and the numbers
                 ! of columns are jb, j2, j3. the superdiagonal elements of a13
                 ! and the subdiagonal elements of a31 lie outside the band.
                 i2 = min(kl - jb,m - j - jb + 1)
                 i3 = min(jb,m - j - kl + 1)
                 ! j2 and j3 are computed after ju has been updated.
                 ! factorize the current block of jb columns
                 loop_80: do jj = j,j + jb - 1
                    ! set fill-in elements in column jj+kv to czero
                    if (jj + kv <= n) then
                       do i = 1,kl
                          ab(i,jj + kv) = czero
                       end do
                    end if
                    ! find pivot and test for singularity. km is the number of
                    ! subdiagonal elements in the current column.
                    km = min(kl,m - jj)
                    jp = la_iwamax(km + 1,ab(kv + 1,jj),1)
                    ipiv(jj) = jp + jj - j
                    if (ab(kv + jp,jj) /= czero) then
                       ju = max(ju,min(jj + ku + jp - 1,n))
                       if (jp /= 1) then
                          ! apply interchange to columns j to j+jb-1
                          if (jp + jj - 1 < j + kl) then
                             call la_wswap(jb,ab(kv + 1 + jj - j,j),ldab - 1,ab(kv + jp + jj - j,j) &
                                       ,ldab - 1)
                          else
                             ! the interchange affects columns j to jj-1 of a31
                             ! which are stored in the work array work31
                             call la_wswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,work31(jp + jj - j - &
                                       kl,1),ldwork)
                             call la_wswap(j + jb - jj,ab(kv + 1,jj),ldab - 1,ab(kv + jp,jj), &
                                       ldab - 1)
                          end if
                       end if
                       ! compute multipliers
                       call la_wscal(km,cone/ab(kv + 1,jj),ab(kv + 2,jj),1)
                       ! update trailing submatrix within the band and within
                       ! the current block. jm is the index of the last column
                       ! which needs to be updated.
                       jm = min(ju,j + jb - 1)
                       if (jm > jj) call la_wgeru(km,jm - jj,-cone,ab(kv + 2,jj),1,ab(kv, &
                                 jj + 1),ldab - 1,ab(kv + 1,jj + 1),ldab - 1)
                    else
                       ! if pivot is czero, set info to the index of the pivot
                       ! unless a czero pivot has already been found.
                       if (info == 0) info = jj
                    end if
                    ! copy current column of a31 into the work array work31
                    nw = min(jj - j + 1,i3)
                    if (nw > 0) call la_wcopy(nw,ab(kv + kl + 1 - jj + j,jj),1,work31(1,jj - j + 1) &
                              ,1)
                 end do loop_80
                 if (j + jb <= n) then
                    ! apply the row interchanges to the other blocks.
                    j2 = min(ju - j + 1,kv) - jb
                    j3 = max(0,ju - j - kv + 1)
                    ! use la_wlaswp to apply the row interchanges to a12, a22, and
                    ! a32.
                    call la_wlaswp(j2,ab(kv + 1 - jb,j + jb),ldab - 1,1,jb,ipiv(j),1)

                    ! adjust the pivot indices.
                    do i = j,j + jb - 1
                       ipiv(i) = ipiv(i) + j - 1
                    end do
                    ! apply the row interchanges to a13, a23, and a33
                    ! columnwise.
                    k2 = j - 1 + jb + j2
                    do i = 1,j3
                       jj = k2 + i
                       do ii = j + i - 1,j + jb - 1
                          ip = ipiv(ii)
                          if (ip /= ii) then
                             temp = ab(kv + 1 + ii - jj,jj)
                             ab(kv + 1 + ii - jj,jj) = ab(kv + 1 + ip - jj,jj)
                             ab(kv + 1 + ip - jj,jj) = temp
                          end if
                       end do
                    end do
                    ! update the relevant part of the trailing submatrix
                    if (j2 > 0) then
                       ! update a12
                       call la_wtrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,j2,cone, &
                                 ab(kv + 1,j),ldab - 1,ab(kv + 1 - jb,j + jb),ldab - 1)
                       if (i2 > 0) then
                          ! update a22
                          call la_wgemm('NO TRANSPOSE','NO TRANSPOSE',i2,j2,jb,-cone,ab( &
                           kv + 1 + jb,j),ldab - 1,ab(kv + 1 - jb,j + jb),ldab - 1,cone,ab(kv + 1,j + jb) &
                                     ,ldab - 1)
                       end if
                       if (i3 > 0) then
                          ! update a32
                          call la_wgemm('NO TRANSPOSE','NO TRANSPOSE',i3,j2,jb,-cone, &
                          work31,ldwork,ab(kv + 1 - jb,j + jb),ldab - 1,cone,ab(kv + kl + 1 - jb,j + jb), &
                                     ldab - 1)
                       end if
                    end if
                    if (j3 > 0) then
                       ! copy the lower triangle of a13 into the work array
                       ! work13
                       do jj = 1,j3
                          do ii = jj,jb
                             work13(ii,jj) = ab(ii - jj + 1,jj + j + kv - 1)
                          end do
                       end do
                       ! update a13 in the work array
                       call la_wtrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,j3,cone, &
                                 ab(kv + 1,j),ldab - 1,work13,ldwork)
                       if (i2 > 0) then
                          ! update a23
                          call la_wgemm('NO TRANSPOSE','NO TRANSPOSE',i2,j3,jb,-cone,ab( &
                           kv + 1 + jb,j),ldab - 1,work13,ldwork,cone,ab(1 + jb,j + kv),ldab - 1)

                       end if
                       if (i3 > 0) then
                          ! update a33
                          call la_wgemm('NO TRANSPOSE','NO TRANSPOSE',i3,j3,jb,-cone, &
                                    work31,ldwork,work13,ldwork,cone,ab(1 + kl,j + kv),ldab - 1)
                       end if
                       ! copy the lower triangle of a13 back into place
                       do jj = 1,j3
                          do ii = jj,jb
                             ab(ii - jj + 1,jj + j + kv - 1) = work13(ii,jj)
                          end do
                       end do
                    end if
                 else
                    ! adjust the pivot indices.
                    do i = j,j + jb - 1
                       ipiv(i) = ipiv(i) + j - 1
                    end do
                 end if
                 ! partially undo the interchanges in the current block to
                 ! restore the upper triangular form of a31 and copy the upper
                 ! triangle of a31 back into place
                 do jj = j + jb - 1,j,-1
                    jp = ipiv(jj) - jj + 1
                    if (jp /= 1) then
                       ! apply interchange to columns j to jj-1
                       if (jp + jj - 1 < j + kl) then
                          ! the interchange does not affect a31
                          call la_wswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,ab(kv + jp + jj - j,j), &
                                     ldab - 1)
                       else
                          ! the interchange does affect a31
                          call la_wswap(jj - j,ab(kv + 1 + jj - j,j),ldab - 1,work31(jp + jj - j - kl, &
                                    1),ldwork)
                       end if
                    end if
                    ! copy the current column of a31 back into place
                    nw = min(i3,jj - j + 1)
                    if (nw > 0) call la_wcopy(nw,work31(1,jj - j + 1),1,ab(kv + kl + 1 - jj + j,jj) &
                              ,1)
                 end do
              end do loop_180
           end if
           return
     end subroutine la_wgbtrf
#endif

     !> CGBTRS: solves a system of linear equations
     !> A * X = B,  A**T * X = B,  or  A**H * X = B
     !> with a general band matrix A using the LU factorization computed
     !> by CGBTRF.

     pure subroutine la_cgbtrs(trans,n,kl,ku,nrhs,ab,ldab,ipiv,b,ldb,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,ldb,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           complex(sp),intent(in) :: ab(ldab,*)
           complex(sp),intent(inout) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lnoti,notran
           integer(ilp) :: i,j,kd,l,lm
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (nrhs < 0) then
              info = -5
           else if (ldab < (2*kl + ku + 1)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('CGBTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           kd = ku + kl + 1
           lnoti = kl > 0
           if (notran) then
              ! solve  a*x = b.
              ! solve l*x = b, overwriting b with x.
              ! l is represented as a product of permutations and unit lower
              ! triangular matrices l = p(1) * l(1) * ... * p(n-1) * l(n-1),
              ! where each transformation l(i) is a rank-cone modification of
              ! the identity matrix.
              if (lnoti) then
                 do j = 1,n - 1
                    lm = min(kl,n - j)
                    l = ipiv(j)
                    if (l /= j) call la_cswap(nrhs,b(l,1),ldb,b(j,1),ldb)
                    call la_cgeru(lm,nrhs,-cone,ab(kd + 1,j),1,b(j,1),ldb,b(j + 1, &
                              1),ldb)
                 end do
              end if
              do i = 1,nrhs
                 ! solve u*x = b, overwriting b with x.
                 call la_ctbsv('UPPER','NO TRANSPOSE','NON-UNIT',n,kl + ku,ab,ldab,b(1, &
                           i),1)
              end do
           else if (la_lsame(trans,'T')) then
              ! solve a**t * x = b.
              do i = 1,nrhs
                 ! solve u**t * x = b, overwriting b with x.
                 call la_ctbsv('UPPER','TRANSPOSE','NON-UNIT',n,kl + ku,ab,ldab,b(1,i) &
                           ,1)
              end do
              ! solve l**t * x = b, overwriting b with x.
              if (lnoti) then
                 do j = n - 1,1,-1
                    lm = min(kl,n - j)
                    call la_cgemv('TRANSPOSE',lm,nrhs,-cone,b(j + 1,1),ldb,ab(kd + 1,j &
                              ),1,cone,b(j,1),ldb)
                    l = ipiv(j)
                    if (l /= j) call la_cswap(nrhs,b(l,1),ldb,b(j,1),ldb)
                 end do
              end if
           else
              ! solve a**h * x = b.
              do i = 1,nrhs
                 ! solve u**h * x = b, overwriting b with x.
                 call la_ctbsv('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',n,kl + ku,ab,ldab, &
                            b(1,i),1)
              end do
              ! solve l**h * x = b, overwriting b with x.
              if (lnoti) then
                 do j = n - 1,1,-1
                    lm = min(kl,n - j)
                    call la_clacgv(nrhs,b(j,1),ldb)
                    call la_cgemv('CONJUGATE TRANSPOSE',lm,nrhs,-cone,b(j + 1,1),ldb, &
                              ab(kd + 1,j),1,cone,b(j,1),ldb)
                    call la_clacgv(nrhs,b(j,1),ldb)
                    l = ipiv(j)
                    if (l /= j) call la_cswap(nrhs,b(l,1),ldb,b(j,1),ldb)
                 end do
              end if
           end if
           return
     end subroutine la_cgbtrs
     !> ZGBTRS: solves a system of linear equations
     !> A * X = B,  A**T * X = B,  or  A**H * X = B
     !> with a general band matrix A using the LU factorization computed
     !> by ZGBTRF.

     pure subroutine la_zgbtrs(trans,n,kl,ku,nrhs,ab,ldab,ipiv,b,ldb,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,ldb,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           complex(dp),intent(in) :: ab(ldab,*)
           complex(dp),intent(inout) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lnoti,notran
           integer(ilp) :: i,j,kd,l,lm
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kl < 0) then
              info = -3
           else if (ku < 0) then
              info = -4
           else if (nrhs < 0) then
              info = -5
           else if (ldab < (2*kl + ku + 1)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -10
           end if
           if (info /= 0) then
