                           ,1)
              end do
              ! solve l**t * x = b, overwriting b with x.
              if (lnoti) then
                 do j = n - 1,1,-1
                    lm = min(kl,n - j)
                    call la_zgemv('TRANSPOSE',lm,nrhs,-cone,b(j + 1,1),ldb,ab(kd + 1,j &
                              ),1,cone,b(j,1),ldb)
                    l = ipiv(j)
                    if (l /= j) call la_zswap(nrhs,b(l,1),ldb,b(j,1),ldb)
                 end do
              end if
           else
              ! solve a**h * x = b.
              do i = 1,nrhs
                 ! solve u**h * x = b, overwriting b with x.
