                           rwork,info)
                 ! multiply by inv(u).
                 call la_ylatrs('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,a,lda,work, &
                           su,rwork(n + 1),info)
              else
                 ! multiply by inv(u**h).
                 call la_ylatrs('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',normin,n,a,lda, &
                            work,su,rwork(n + 1),info)
                 ! multiply by inv(l**h).
                 call la_ylatrs('LOWER','CONJUGATE TRANSPOSE','UNIT',normin,n,a,lda, &
                           work,sl,rwork,info)
              end if
              ! divide x by 1/(sl*su) if doing so will not cause overflow.
              scale = sl*su
              normin = 'Y'
              if (scale /= one) then
                 ix = la_iyamax(n,work,1)
                 if (scale < cabs1(work(ix))*smlnum .or. scale == zero) go to 20
                 call la_yxrscl(n,scale,work,1)
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           20 continue
           return
     end subroutine la_ygecon
#endif
#ifdef LA_WITH_QP
     !> WGECON: estimates the reciprocal of the condition number of a general
     !> complex matrix A, in either the 1-norm or the infinity-norm, using
     !> the LU factorization computed by WGETRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as
     !> RCOND = 1 / ( norm(A) * norm(inv(A)) ).

     pure subroutine la_wgecon(norm,n,a,lda,anorm,rcond,work,rwork,info)
        use la_constants_qp,only:zero,one
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: norm
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           real(qp),intent(in) :: anorm
           real(qp),intent(out) :: rcond
           ! Array Arguments
           real(qp),intent(out) :: rwork(*)
           complex(qp),intent(inout) :: a(lda,*)
           complex(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: onenrm
           character :: normin
           integer(ilp) :: ix,kase,kase1
           real(qp) :: ainvnm,scale,sl,smlnum,su
           complex(qp) :: zdum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,real,aimag,max
           ! Statement Functions
           real(qp) :: cabs1
           ! Statement Function Definitions
           cabs1(zdum) = abs(real(zdum,KIND=qp)) + abs(aimag(zdum))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           onenrm = norm == '1' .or. la_lsame(norm,'O')
           if (.not. onenrm .and. .not. la_lsame(norm,'I')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (anorm < zero) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('WGECON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           smlnum = la_qlamch('SAFE MINIMUM')
           ! estimate the norm of inv(a).
           ainvnm = zero
           normin = 'N'
           if (onenrm) then
              kase1 = 1
           else
              kase1 = 2
           end if
           kase = 0
           10 continue
           call la_wlacn2(n,work(n + 1),work,ainvnm,kase,isave)
           if (kase /= 0) then
              if (kase == kase1) then
                 ! multiply by inv(l).
                 call la_wlatrs('LOWER','NO TRANSPOSE','UNIT',normin,n,a,lda,work,sl, &
                           rwork,info)
                 ! multiply by inv(u).
                 call la_wlatrs('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,a,lda,work, &
                           su,rwork(n + 1),info)
              else
                 ! multiply by inv(u**h).
                 call la_wlatrs('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',normin,n,a,lda, &
                            work,su,rwork(n + 1),info)
                 ! multiply by inv(l**h).
                 call la_wlatrs('LOWER','CONJUGATE TRANSPOSE','UNIT',normin,n,a,lda, &
                           work,sl,rwork,info)
              end if
              ! divide x by 1/(sl*su) if doing so will not cause overflow.
              scale = sl*su
              normin = 'Y'
              if (scale /= one) then
                 ix = la_iwamax(n,work,1)
                 if (scale < cabs1(work(ix))*smlnum .or. scale == zero) go to 20
                 call la_wqrscl(n,scale,work,1)
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           20 continue
           return
     end subroutine la_wgecon
#endif

     !> CGESC2: solves a system of linear equations
     !> A * X = scale* RHS
     !> with a general N-by-N matrix A using the LU factorization with
     !> complete pivoting computed by CGETC2.

     pure subroutine la_cgesc2(n,a,lda,rhs,ipiv,jpiv,scale)
        use la_constants_sp,only:zero,one,two
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: lda,n
           real(sp),intent(out) :: scale
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*),jpiv(*)
           complex(sp),intent(in) :: a(lda,*)
           complex(sp),intent(inout) :: rhs(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j
           real(sp) :: bignum,eps,smlnum
           complex(sp) :: temp
           ! Intrinsic Functions
           intrinsic :: abs,cmplx,real
           ! Executable Statements
           ! set constant to control overflow
           eps = la_slamch('P')
           smlnum = la_slamch('S')/eps
           bignum = one/smlnum
           call la_slabad(smlnum,bignum)
           ! apply permutations ipiv to rhs
           call la_claswp(1,rhs,lda,1,n - 1,ipiv,1)
           ! solve for l part
           do i = 1,n - 1
              do j = i + 1,n
                 rhs(j) = rhs(j) - a(j,i)*rhs(i)
              end do
           end do
           ! solve for u part
           scale = one
           ! check for scaling
           i = la_icamax(n,rhs,1)
           if (two*smlnum*abs(rhs(i)) > abs(a(n,n))) then
              temp = cmplx(one/two,zero,KIND=sp)/abs(rhs(i))
              call la_cscal(n,temp,rhs(1),1)
              scale = scale*real(temp,KIND=sp)
           end if
           do i = n,1,-1
              temp = cmplx(one,zero,KIND=sp)/a(i,i)
              rhs(i) = rhs(i)*temp
              do j = i + 1,n
                 rhs(i) = rhs(i) - rhs(j)*(a(i,j)*temp)
              end do
           end do
           ! apply permutations jpiv to the solution (rhs)
           call la_claswp(1,rhs,lda,1,n - 1,jpiv,-1)
           return
     end subroutine la_cgesc2
