           ! quick return if possible
           if (m == 0 .or. n == 0) return
           if (m == 1) then
              ! use unblocked code for cone row case
              ! just need to handle ipiv and info
              ipiv(1) = 1
              if (a(1,1) == czero) info = 1
           else if (n == 1) then
              ! use unblocked code for cone column case
              ! compute machine safe minimum
              sfmin = la_dlamch('S')
              ! find pivot and test for singularity
              i = la_izamax(m,a(1,1),1)
              ipiv(1) = i
              if (a(i,1) /= czero) then
                 ! apply the interchange
                 if (i /= 1) then
                    temp = a(1,1)
                    a(1,1) = a(i,1)
                    a(i,1) = temp
                 end if
                 ! compute elements 2:m of the column
                 if (abs(a(1,1)) >= sfmin) then
                    call la_zscal(m - 1,cone/a(1,1),a(2,1),1)
                 else
                    do i = 1,m - 1
                       a(1 + i,1) = a(1 + i,1)/a(1,1)
                    end do
                 end if
              else
                 info = 1
              end if
           else
              ! use recursive code
              n1 = min(m,n)/2
              n2 = n - n1
                     ! [ a11 ]
              ! factor [ --- ]
                     ! [ a21 ]
              call la_zgetrf2(m,n1,a,lda,ipiv,iinfo)
              if (info == 0 .and. iinfo > 0) info = iinfo
                                    ! [ a12 ]
              ! apply interchanges to [ --- ]
                                    ! [ a22 ]
              call la_zlaswp(n2,a(1,n1 + 1),lda,1,n1,ipiv,1)
              ! solve a12
              call la_ztrsm('L','L','N','U',n1,n2,cone,a,lda,a(1,n1 + 1),lda)

              ! update a22
              call la_zgemm('N','N',m - n1,n2,n1,-cone,a(n1 + 1,1),lda,a(1,n1 + 1), &
                        lda,cone,a(n1 + 1,n1 + 1),lda)
              ! factor a22
              call la_zgetrf2(m - n1,n2,a(n1 + 1,n1 + 1),lda,ipiv(n1 + 1),iinfo)
              ! adjust info and the pivot indices
              if (info == 0 .and. iinfo > 0) info = iinfo + n1
              do i = n1 + 1,min(m,n)
                 ipiv(i) = ipiv(i) + n1
              end do
