              do j = n,1,-1
                 ! copy current column of l to work and replace with zeros.
                 do i = j + 1,n
                    work(i) = a(i,j)
                    a(i,j) = czero
                 end do
                 ! compute current column of inv(a).
                 if (j < n) call la_wgemv('NO TRANSPOSE',n,n - j,-cone,a(1,j + 1),lda,work( &
                            j + 1),1,cone,a(1,j),1)
              end do
           else
              ! use blocked code.
              nn = ((n - 1)/nb)*nb + 1
              do j = nn,1,-nb
                 jb = min(nb,n - j + 1)
                 ! copy current block column of l to work and replace with
                 ! zeros.
                 do jj = j,j + jb - 1
                    do i = jj + 1,n
                       work(i + (jj - j)*ldwork) = a(i,jj)
                       a(i,jj) = czero
                    end do
                 end do
                 ! compute current block column of inv(a).
                 if (j + jb <= n) call la_wgemm('NO TRANSPOSE','NO TRANSPOSE',n,jb,n - j - jb + 1,- &
                           cone,a(1,j + jb),lda,work(j + jb),ldwork,cone,a(1,j),lda)
                 call la_wtrsm('RIGHT','LOWER','NO TRANSPOSE','UNIT',n,jb,cone,work(j &
                           ),ldwork,a(1,j),lda)
              end do
           end if
           ! apply column interchanges.
           do j = n - 1,1,-1
              jp = ipiv(j)
              if (jp /= j) call la_wswap(n,a(1,j),1,a(1,jp),1)
           end do
           work(1) = iws
           return
     end subroutine la_wgetri
#endif

     !> CGETRS: solves a system of linear equations
     !> A * X = B,  A**T * X = B,  or  A**H * X = B
     !> with a general N-by-N matrix A using the LU factorization computed
     !> by CGETRF.

     pure subroutine la_cgetrs(trans,n,nrhs,a,lda,ipiv,b,ldb,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           complex(sp),intent(in) :: a(lda,*)
           complex(sp),intent(inout) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: notran
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('CGETRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           if (notran) then
              ! solve a * x = b.
              ! apply row interchanges to the right hand sides.
              call la_claswp(nrhs,b,ldb,1,n,ipiv,1)
              ! solve l*x = b, overwriting b with x.
              call la_ctrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',n,nrhs,cone,a,lda,b, &
                         ldb)
              ! solve u*x = b, overwriting b with x.
              call la_ctrsm('LEFT','UPPER','NO TRANSPOSE','NON-UNIT',n,nrhs,cone,a, &
                        lda,b,ldb)
           else
              ! solve a**t * x = b  or a**h * x = b.
              ! solve u**t *x = b or u**h *x = b, overwriting b with x.
              call la_ctrsm('LEFT','UPPER',trans,'NON-UNIT',n,nrhs,cone,a,lda,b,ldb &
                        )
              ! solve l**t *x = b, or l**h *x = b overwriting b with x.
              call la_ctrsm('LEFT','LOWER',trans,'UNIT',n,nrhs,cone,a,lda,b,ldb)

              ! apply row interchanges to the solution vectors.
              call la_claswp(nrhs,b,ldb,1,n,ipiv,-1)
           end if
           return
