           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           complex(sp),intent(inout) :: b(ldb,*)
           complex(sp),intent(in) :: d(*),dl(*),du(*),du2(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: notran
           integer(ilp) :: itrans,j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           info = 0
           notran = (trans == 'N' .or. trans == 'N')
           if (.not. notran .and. .not. (trans == 'T' .or. trans == 'T') .and. .not. (trans == 'C' .or. &
                     trans == 'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(n,1)) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('CGTTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           ! decode trans
           if (notran) then
              itrans = 0
           else if (trans == 'T' .or. trans == 'T') then
              itrans = 1
           else
              itrans = 2
           end if
           ! determine the number of right-hand sides to solve at a time.
           if (nrhs == 1) then
              nb = 1
           else
              nb = max(1,la_ilaenv(1,'CGTTRS',trans,n,nrhs,-1,-1))
