     !> CLATDF: computes the contribution to the reciprocal Dif-estimate
     !> by solving for x in Z * x = b, where b is chosen such that the norm
     !> of x is as large as possible. It is assumed that LU decomposition
     !> of Z has been computed by CGETC2. On entry RHS = f holds the
     !> contribution from earlier solved sub-systems, and on return RHS = x.
     !> The factorization of Z returned by CGETC2 has the form
     !> Z = P * L * U * Q, where P and Q are permutation matrices. L is lower
     !> triangular with unit diagonal elements and U is upper triangular.

     pure subroutine la_clatdf(ijob,n,z,ldz,rhs,rdsum,rdscal,ipiv,jpiv)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ijob,ldz,n
           real(sp),intent(inout) :: rdscal,rdsum
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*),jpiv(*)
           complex(sp),intent(inout) :: rhs(*),z(ldz,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: maxdim = 2

           ! Local Scalars
           integer(ilp) :: i,info,j,k
           real(sp) :: rtemp,scale,sminu,splus
           complex(sp) :: bm,bp,pmone,temp
           ! Local Arrays
           real(sp) :: rwork(maxdim)
           complex(sp) :: work(4*maxdim),xm(maxdim),xp(maxdim)
           ! Intrinsic Functions
           intrinsic :: abs,real,sqrt
           ! Executable Statements
           if (ijob /= 2) then
              ! apply permutations ipiv to rhs
              call la_claswp(1,rhs,ldz,1,n - 1,ipiv,1)
              ! solve for l-part choosing rhs either to +1 or -1.
              pmone = -cone
              loop_10: do j = 1,n - 1
                 bp = rhs(j) + cone
                 bm = rhs(j) - cone
                 splus = one
                 ! lockahead for l- part rhs(1:n-1) = +-1
                 ! splus and smin computed more efficiently than in bsolve[1].
                 splus = splus + real(la_cdotc(n - j,z(j + 1,j),1,z(j + 1,j),1),KIND=sp)

                 sminu = real(la_cdotc(n - j,z(j + 1,j),1,rhs(j + 1),1),KIND=sp)
                 splus = splus*real(rhs(j),KIND=sp)
                 if (splus > sminu) then
                    rhs(j) = bp
                 else if (sminu > splus) then
                    rhs(j) = bm
                 else
                    ! in this case the updating sums are equal and we can
                    ! choose rhs(j) +1 or -1. the first time this happens we
                    ! choose -1, thereafter +1. this is a simple way to get
                    ! good estimates of matrices like byers well-known example
                    ! (see [1]). (not done in bsolve.)
                    rhs(j) = rhs(j) + pmone
                    pmone = cone
                 end if
                 ! compute the remaining r.h.s.
                 temp = -rhs(j)
                 call la_caxpy(n - j,temp,z(j + 1,j),1,rhs(j + 1),1)
              end do loop_10
              ! solve for u- part, lockahead for rhs(n) = +-1. this is not done
              ! in bsolve and will hopefully give us a better estimate because
              ! any ill-conditioning of the original matrix is transferred to u
              ! and not to l. u(n, n) is an approximation to sigma_min(lu).
              call la_ccopy(n - 1,rhs,1,work,1)
              work(n) = rhs(n) + cone
              rhs(n) = rhs(n) - cone
              splus = zero
              sminu = zero
              do i = n,1,-1
                 temp = cone/z(i,i)
                 work(i) = work(i)*temp
                 rhs(i) = rhs(i)*temp
                 do k = i + 1,n
                    work(i) = work(i) - work(k)*(z(i,k)*temp)
                    rhs(i) = rhs(i) - rhs(k)*(z(i,k)*temp)
                 end do
                 splus = splus + abs(work(i))
                 sminu = sminu + abs(rhs(i))
              end do
              if (splus > sminu) call la_ccopy(n,work,1,rhs,1)
              ! apply the permutations jpiv to the computed solution (rhs)
              call la_claswp(1,rhs,ldz,1,n - 1,jpiv,-1)
              ! compute the sum of squares
              call la_classq(n,rhs,1,rdscal,rdsum)
              return
           end if
           ! entry ijob = 2
           ! compute approximate nullvector xm of z
           call la_cgecon('I',n,z,ldz,one,rtemp,work,rwork,info)
           call la_ccopy(n,work(n + 1),1,xm,1)
           ! compute rhs
           call la_claswp(1,xm,ldz,1,n - 1,ipiv,-1)
           temp = cone/sqrt(la_cdotc(n,xm,1,xm,1))
           call la_cscal(n,temp,xm,1)
           call la_ccopy(n,xm,1,xp,1)
           call la_caxpy(n,cone,rhs,1,xp,1)
           call la_caxpy(n,-cone,xm,1,rhs,1)
           call la_cgesc2(n,z,ldz,rhs,ipiv,jpiv,scale)
           call la_cgesc2(n,z,ldz,xp,ipiv,jpiv,scale)
           if (la_scasum(n,xp,1) > la_scasum(n,rhs,1)) call la_ccopy(n,xp,1, &
                     rhs,1)
           ! compute the sum of squares
           call la_classq(n,rhs,1,rdscal,rdsum)
           return
     end subroutine la_clatdf
