                 ! apply interchanges to columns 1:j-1.
                 call la_zlaswp(j - 1,a,lda,j,j + jb - 1,ipiv,1)
                 if (j + jb <= n) then
                    ! apply interchanges to columns j+jb:n.
                    call la_zlaswp(n - j - jb + 1,a(1,j + jb),lda,j,j + jb - 1,ipiv,1)
                    ! compute block row of u.
                    call la_ztrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,n - j - jb + 1,cone, &
                               a(j,j),lda,a(j,j + jb),lda)
                    if (j + jb <= m) then
                       ! update trailing submatrix.
                       call la_zgemm('NO TRANSPOSE','NO TRANSPOSE',m - j - jb + 1,n - j - jb + 1,jb,- &
                       cone,a(j + jb,j),lda,a(j,j + jb),lda,cone,a(j + jb,j + jb),lda)

                    end if
                 end if
              end do
           end if
           return
     end subroutine la_zgetrf
