        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,iinfo,j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('WGETRF',-info)
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) return
           ! determine the block size for this environment.
           nb = la_ilaenv(1,'WGETRF',' ',m,n,-1,-1)
           if (nb <= 1 .or. nb >= min(m,n)) then
              ! use unblocked code.
              call la_wgetrf2(m,n,a,lda,ipiv,info)
           else
              ! use blocked code.
              do j = 1,min(m,n),nb
                 jb = min(min(m,n) - j + 1,nb)
                 ! factor diagonal and subdiagonal blocks and test for exact
                 ! singularity.
                 call la_wgetrf2(m - j + 1,jb,a(j,j),lda,ipiv(j),iinfo)
                 ! adjust info and the pivot indices.
                 if (info == 0 .and. iinfo > 0) info = iinfo + j - 1
                 do i = j,min(m,j + jb - 1)
                    ipiv(i) = j - 1 + ipiv(i)
                 end do
                 ! apply interchanges to columns 1:j-1.
                 call la_wlaswp(j - 1,a,lda,j,j + jb - 1,ipiv,1)
                 if (j + jb <= n) then
                    ! apply interchanges to columns j+jb:n.
                    call la_wlaswp(n - j - jb + 1,a(1,j + jb),lda,j,j + jb - 1,ipiv,1)
                    ! compute block row of u.
                    call la_wtrsm('LEFT','LOWER','NO TRANSPOSE','UNIT',jb,n - j - jb + 1,cone, &
                               a(j,j),lda,a(j,j + jb),lda)
                    if (j + jb <= m) then
                       ! update trailing submatrix.
                       call la_wgemm('NO TRANSPOSE','NO TRANSPOSE',m - j - jb + 1,n - j - jb + 1,jb,- &
                       cone,a(j + jb,j),lda,a(j,j + jb),lda,cone,a(j + jb,j + jb),lda)

                    end if
                 end if
              end do
           end if
           return
     end subroutine la_wgetrf
#endif

     !> CGTCON: estimates the reciprocal of the condition number of a complex
     !> tridiagonal matrix A using the LU factorization as computed by
     !> CGTTRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as RCOND = 1 / (ANORM * norm(inv(A))).

     pure subroutine la_cgtcon(norm,n,dl,d,du,du2,ipiv,anorm,rcond,work,info)
        use la_constants_sp

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: norm
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           real(sp),intent(in) :: anorm
           real(sp),intent(out) :: rcond
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           complex(sp),intent(in) :: d(*),dl(*),du(*),du2(*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: onenrm
           integer(ilp) :: i,kase,kase1
           real(sp) :: ainvnm
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: cmplx
           ! Executable Statements
           ! test the input arguments.
           info = 0
           onenrm = norm == '1' .or. la_lsame(norm,'O')
           if (.not. onenrm .and. .not. la_lsame(norm,'I')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (anorm < zero) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('CGTCON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           ! check that d(1:n) is non-zero.
           do i = 1,n
              if (d(i) == cmplx(zero,KIND=sp)) return
           end do
           ainvnm = zero
           if (onenrm) then
              kase1 = 1
           else
              kase1 = 2
           end if
           kase = 0
           20 continue
           call la_clacn2(n,work(n + 1),work,ainvnm,kase,isave)
           if (kase /= 0) then
              if (kase == kase1) then
                 ! multiply by inv(u)*inv(l).
                 call la_cgttrs('NO TRANSPOSE',n,1,dl,d,du,du2,ipiv,work,n,info)

              else
                 ! multiply by inv(l**h)*inv(u**h).
                 call la_cgttrs('CONJUGATE TRANSPOSE',n,1,dl,d,du,du2,ipiv,work,n, &
                           info)
              end if
              go to 20
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           return
     end subroutine la_cgtcon
