     !> CGTRFS: improves the computed solution to a system of linear
     !> equations when the coefficient matrix is tridiagonal, and provides
     !> error bounds and backward error estimates for the solution.

     pure subroutine la_cgtrfs(trans,n,nrhs,dl,d,du,dlf,df,duf,du2,ipiv,b,ldb,x, &
               ldx,ferr,berr,work,rwork,info)
        use la_constants_sp,only:zero,one,two,three
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,ldx,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(sp),intent(out) :: berr(*),ferr(*),rwork(*)
           complex(sp),intent(in) :: b(ldb,*),d(*),df(*),dl(*),dlf(*),du(*),du2(*),duf(*)

           complex(sp),intent(out) :: work(*)
           complex(sp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           logical(lk) :: notran
           character :: transn,transt
           integer(ilp) :: count,i,j,kase,nz
           real(sp) :: eps,lstres,s,safe1,safe2,safmin
           complex(sp) :: zdum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,aimag,cmplx,max,real
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(zdum) = abs(real(zdum,KIND=sp)) + abs(aimag(zdum))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(1,n)) then
              info = -13
           else if (ldx < max(1,n)) then
              info = -15
           end if
           if (info /= 0) then
              call la_xerbla('CGTRFS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) then
              do j = 1,nrhs
                 ferr(j) = zero
                 berr(j) = zero
              end do
              return
           end if
           if (notran) then
              transn = 'N'
              transt = 'C'
           else
              transn = 'C'
              transt = 'N'
           end if
           ! nz = maximum number of nonzero elements in each row of a, plus 1
           nz = 4
           eps = la_slamch('EPSILON')
           safmin = la_slamch('SAFE MINIMUM')
           safe1 = nz*safmin
           safe2 = safe1/eps
           ! do for each right hand side
           loop_110: do j = 1,nrhs
              count = 1
              lstres = three
              20 continue
              ! loop until stopping criterion is satisfied.
              ! compute residual r = b - op(a) * x,
              ! where op(a) = a, a**t, or a**h, depending on trans.
              call la_ccopy(n,b(1,j),1,work,1)
              call la_clagtm(trans,n,1,-one,dl,d,du,x(1,j),ldx,one,work,n)

              ! compute abs(op(a))*abs(x) + abs(b) for use in the backward
              ! error bound.
              if (notran) then
                 if (n == 1) then
                    rwork(1) = cabs1(b(1,j)) + cabs1(d(1))*cabs1(x(1,j))
                 else
                    rwork(1) = cabs1(b(1,j)) + cabs1(d(1))*cabs1(x(1,j)) + cabs1( &
                              du(1))*cabs1(x(2,j))
                    do i = 2,n - 1
                       rwork(i) = cabs1(b(i,j)) + cabs1(dl(i - 1))*cabs1(x(i - 1,j)) + &
                       cabs1(d(i))*cabs1(x(i,j)) + cabs1(du(i))*cabs1(x(i + 1,j))

                    end do
                    rwork(n) = cabs1(b(n,j)) + cabs1(dl(n - 1))*cabs1(x(n - 1,j)) + &
                              cabs1(d(n))*cabs1(x(n,j))
                 end if
              else
                 if (n == 1) then
                    rwork(1) = cabs1(b(1,j)) + cabs1(d(1))*cabs1(x(1,j))
                 else
                    rwork(1) = cabs1(b(1,j)) + cabs1(d(1))*cabs1(x(1,j)) + cabs1( &
                              dl(1))*cabs1(x(2,j))
                    do i = 2,n - 1
                       rwork(i) = cabs1(b(i,j)) + cabs1(du(i - 1))*cabs1(x(i - 1,j)) + &
                       cabs1(d(i))*cabs1(x(i,j)) + cabs1(dl(i))*cabs1(x(i + 1,j))

                    end do
                    rwork(n) = cabs1(b(n,j)) + cabs1(du(n - 1))*cabs1(x(n - 1,j)) + &
                              cabs1(d(n))*cabs1(x(n,j))
                 end if
              end if
              ! compute componentwise relative backward error from formula
              ! max(i) ( abs(r(i)) / ( abs(op(a))*abs(x) + abs(b) )(i) )
              ! where abs(z) is the componentwise absolute value of the matrix
              ! or vector z.  if the i-th component of the denominator is less
              ! than safe2, then safe1 is added to the i-th components of the
              ! numerator and denominator before dividing.
              s = zero
              do i = 1,n
                 if (rwork(i) > safe2) then
                    s = max(s,cabs1(work(i))/rwork(i))
                 else
                    s = max(s, (cabs1(work(i)) + safe1)/(rwork(i) + safe1))
                 end if
              end do
              berr(j) = s
              ! test stopping criterion. continue iterating if
                 ! 1) the residual berr(j) is larger than machine epsilon, and
                 ! 2) berr(j) decreased by at least a factor of 2 during the
                    ! last iteration, and
                 ! 3) at most itmax iterations tried.
              if (berr(j) > eps .and. two*berr(j) <= lstres .and. count <= itmax) then
                 ! update solution and try again.
                 call la_cgttrs(trans,n,1,dlf,df,duf,du2,ipiv,work,n,info)
                 call la_caxpy(n,cmplx(one,KIND=sp),work,1,x(1,j),1)
                 lstres = berr(j)
                 count = count + 1
                 go to 20
              end if
              ! bound error from formula
              ! norm(x - xtrue) / norm(x) .le. ferr =
              ! norm( abs(inv(op(a)))*
                 ! ( abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) ))) / norm(x)
              ! where
                ! norm(z) is the magnitude of the largest component of z
                ! inv(op(a)) is the inverse of op(a)
                ! abs(z) is the componentwise absolute value of the matrix or
                   ! vector z
                ! nz is the maximum number of nonzeros in any row of a, plus 1
                ! eps is machine epsilon
              ! the i-th component of abs(r)+nz*eps*(abs(op(a))*abs(x)+abs(b))
              ! is incremented by safe1 if the i-th component of
              ! abs(op(a))*abs(x) + abs(b) is less than safe2.
              ! use la_clacn2 to estimate the infinity-norm of the matrix
                 ! inv(op(a)) * diag(w),
              ! where w = abs(r) + nz*eps*( abs(op(a))*abs(x)+abs(b) )))
              do i = 1,n
                 if (rwork(i) > safe2) then
                    rwork(i) = cabs1(work(i)) + nz*eps*rwork(i)
                 else
                    rwork(i) = cabs1(work(i)) + nz*eps*rwork(i) + safe1
                 end if
              end do
              kase = 0
              70 continue
              call la_clacn2(n,work(n + 1),work,ferr(j),kase,isave)
              if (kase /= 0) then
                 if (kase == 1) then
                    ! multiply by diag(w)*inv(op(a)**h).
                    call la_cgttrs(transt,n,1,dlf,df,duf,du2,ipiv,work,n,info)

                    do i = 1,n
                       work(i) = rwork(i)*work(i)
                    end do
                 else
                    ! multiply by inv(op(a))*diag(w).
                    do i = 1,n
                       work(i) = rwork(i)*work(i)
                    end do
                    call la_cgttrs(transn,n,1,dlf,df,duf,du2,ipiv,work,n,info)

                 end if
                 go to 70
              end if
              ! normalize error.
              lstres = zero
              do i = 1,n
                 lstres = max(lstres,cabs1(x(i,j)))
              end do
              if (lstres /= zero) ferr(j) = ferr(j)/lstres
           end do loop_110
           return
     end subroutine la_cgtrfs
     !> ZGTRFS: improves the computed solution to a system of linear
     !> equations when the coefficient matrix is tridiagonal, and provides
     !> error bounds and backward error estimates for the solution.

     pure subroutine la_zgtrfs(trans,n,nrhs,dl,d,du,dlf,df,duf,du2,ipiv,b,ldb,x, &
               ldx,ferr,berr,work,rwork,info)
        use la_constants_dp,only:zero,one,two,three
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,ldx,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(dp),intent(out) :: berr(*),ferr(*),rwork(*)
           complex(dp),intent(in) :: b(ldb,*),d(*),df(*),dl(*),dlf(*),du(*),du2(*),duf(*)

           complex(dp),intent(out) :: work(*)
           complex(dp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           logical(lk) :: notran
           character :: transn,transt
           integer(ilp) :: count,i,j,kase,nz
           real(dp) :: eps,lstres,s,safe1,safe2,safmin
           complex(dp) :: zdum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,aimag,max
           ! Statement Functions
           real(dp) :: cabs1
           ! Statement Function Definitions
           cabs1(zdum) = abs(real(zdum,KIND=dp)) + abs(aimag(zdum))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T') .and. .not. la_lsame(trans, &
                     'C')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(1,n)) then
              info = -13
           else if (ldx < max(1,n)) then
              info = -15
           end if
           if (info /= 0) then
              call la_xerbla('ZGTRFS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) then
              do j = 1,nrhs
                 ferr(j) = zero
                 berr(j) = zero
              end do
              return
           end if
           if (notran) then
              transn = 'N'
              transt = 'C'
           else
              transn = 'C'
              transt = 'N'
           end if
           ! nz = maximum number of nonzero elements in each row of a, plus 1
           nz = 4
           eps = la_dlamch('EPSILON')
           safmin = la_dlamch('SAFE MINIMUM')
           safe1 = nz*safmin
           safe2 = safe1/eps
           ! do for each right hand side
           loop_110: do j = 1,nrhs
              count = 1
              lstres = three
              20 continue
              ! loop until stopping criterion is satisfied.
              ! compute residual r = b - op(a) * x,
              ! where op(a) = a, a**t, or a**h, depending on trans.
              call la_zcopy(n,b(1,j),1,work,1)
              call la_zlagtm(trans,n,1,-one,dl,d,du,x(1,j),ldx,one,work,n)

              ! compute abs(op(a))*abs(x) + abs(b) for use in the backward
              ! error bound.
              if (notran) then
                 if (n == 1) then
                    rwork(1) = cabs1(b(1,j)) + cabs1(d(1))*cabs1(x(1,j))
                 else
                    rwork(1) = cabs1(b(1,j)) + cabs1(d(1))*cabs1(x(1,j)) + cabs1( &
                              du(1))*cabs1(x(2,j))
                    do i = 2,n - 1
                       rwork(i) = cabs1(b(i,j)) + cabs1(dl(i - 1))*cabs1(x(i - 1,j)) + &
